// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"bounds":{"id":"bounds","prerequisites":["negation","monotone-bounded"],"next":["max-min"],"related":["archimedean-property","sup-inf"],"objectives":["寫得出上界、下界、有界的定義，並知道上界不唯一。","會用不等式找出一個上界並證明它真的是上界。","會用否定形式證明集合或函數「沒有上界」。"],"concept":[{"heading":"① 天花板與地板","body":["集合 $S=\\{\\frac{1}{2},\\frac{2}{3},\\frac{3}{4},\\dots\\}$ 的每個數都不超過 1，1 就是一個「天花板」。天花板不只一個：1.5、100 也都不會被超過。這一章要問的是：天花板什麼時候存在、最低的天花板在哪裡、它是不是集合自己的元素。這一課先把「天花板」講精確。"]},{"heading":"② 定義","body":["設 $S\\subseteq\\mathbb{R}$。若存在實數 $M$，使得對所有 $x\\in S$ 都有 $x\\le M$，就說 $S$ 有上界，$M$ 是 $S$ 的一個上界。下界對稱：對所有 $x\\in S$，$x\\ge m$。","既有上界又有下界，叫做有界。等價的寫法是：存在 $K>0$，使得對所有 $x\\in S$，$|x|\\le K$（取 $K=\\max(|m|,|M|)$ 就從前者得到後者）。","函數 $f$ 在集合 $A$ 上有上界，指的是值域 $\\{f(x):x\\in A\\}$ 有上界；數列有界指的是 $\\{a_n:n\\in\\mathbb{N}\\}$ 有界。"],"tex":["S\\text{ 有上界}\\iff\\exists M\\in\\mathbb{R}\\ \\forall x\\in S,\\ x\\le M"]},{"heading":"③ 沒有上界怎麼寫","body":["照〈否定〉翻：$S$ 沒有上界 $\\iff$ 對每一個 $M$，都存在 $x\\in S$ 使 $x>M$。人話：不管你把天花板放多高，總有元素穿過去。","注意順序：先給 $M$，再找 $x$，$x$ 可以依賴 $M$。"]},{"heading":"④ 找上界的手法","body":["把式子改寫成「常數減一個正數」或用已知不等式放大：$\\frac{3n-1}{n+2}=3-\\frac{7}{n+2}$，一眼看出每項都 $<3$。放大時不必找最好的界，夠用就好；最好的界是〈上確界與下確界〉的事。"]}],"workedExamples":[{"title":"數列集合的上下界","prompt":"$S=\\{\\frac{3n-1}{n+2}:n\\in\\mathbb{N}\\}$。找一個上界與一個下界，並證明。","steps":["改寫：$\\frac{3n-1}{n+2}=\\frac{3(n+2)-7}{n+2}=3-\\frac{7}{n+2}$。","上界：$n+2>0$，所以 $\\frac{7}{n+2}>0$，每項都 $<3$。3 是上界。","下界：$n\\ge1$ 時 $n+2\\ge3$，$\\frac{7}{n+2}\\le\\frac{7}{3}$，每項 $\\ge3-\\frac{7}{3}=\\frac{2}{3}$。$\\frac{2}{3}$ 是下界（而且 $n=1$ 時取到）。"],"answer":"上界 3，下界 $\\frac{2}{3}$；$S$ 有界"},{"title":"證明沒有上界","prompt":"證明 $S=\\{n^2:n\\in\\mathbb{N}\\}$ 沒有上界。","steps":["要證：對每個 $M$，存在 $n\\in\\mathbb{N}$ 使 $n^2>M$。","任意給定 $M$。由〈阿基米德性質〉，存在自然數 $n>M$。","$n\\ge1$，所以 $n^2\\ge n>M$。這個 $n$ 就是要找的元素。"],"answer":"給定 $M$，取自然數 $n>M$，則 $n^2\\ge n>M$","note":"「存在比 $M$ 大的自然數」看起來理所當然，但它需要證明，見〈阿基米德性質〉。"},{"title":"函數有界","prompt":"證明 $f(x)=\\frac{x}{1+x^2}$ 在 $\\mathbb{R}$ 上有界。","steps":["從平方非負出發：$(|x|-1)^2\\ge0$，展開 $x^2-2|x|+1\\ge0$，所以 $2|x|\\le1+x^2$。","$1+x^2>0$，兩邊除以 $2(1+x^2)$：$|x|/(1+x^2)\\le\\frac{1}{2}$。","$|f(x)|=|x|/(1+x^2)\\le\\frac{1}{2}$ 對所有實數 $x$ 成立，所以 $f$ 有界（$K=\\frac{1}{2}$）。"],"answer":"$|f(x)|\\le\\frac{1}{2}$ 對所有 $x$ 成立"}],"pitfalls":["以為上界要屬於集合。3 是 $\\{3-\\frac{7}{n+2}\\}$ 的上界，但不是其中的元素。","說「上界是 3」，好像上界只有一個。3、4、100 都是上界。","「沒有上界」寫成「存在 $x$ 使 $x>M$」卻沒說 $M$ 是任意的；量詞順序是 $\\forall M\\ \\exists x$。","只檢查前幾項就說找到上界，沒有證明對所有 $n$ 成立。"],"voice":"eb64c60b","sections":[{"title":"天花板","beats":[{"show":["$S=\\{\\frac{1}{2},\\frac{2}{3},\\frac{3}{4},\\dots\\}$"],"note":"每個數都不超過 1。","say":"二分之一、三分之二、四分之三，一直下去。每一個都不超過一，一就像是一片天花板。","board":[{"do":"write","line":"$S=\\{\\frac{1}{2},\\frac{2}{3},\\frac{3}{4},\\dots\\}$"},{"do":"write","line":"每個數 $\\le {{u:1}}$","on":"每一個"},{"do":"focus","term":"u","label":"天花板","on":"一就像是"}],"t":[0,9468]},{"show":["1.5、100 也都是天花板"],"note":"上界不只一個。","say":"天花板不只一片：一點五、一百，也都不會被超過。所以不要說上界是誰，要說一個上界。","board":[{"do":"write","line":"$x\\le 1.5$、$x\\le 100$"}],"t":[9756,19512]},{"show":["上界不必屬於集合"],"note":"1 是上界，但不在 $S$ 裡。","say":"還有，一不是這個集合的元素，可是它照樣是上界。上界只要不被超過，不用住在集合裡。","board":[{"do":"write","line":"${{o:1}}\\notin S$，但 $1$ 仍是上界"},{"do":"focus","term":"o","on":"照樣"}],"t":[19800,29376]}],"check":0},{"title":"定義","beats":[{"show":["$\\exists M\\in\\mathbb{R}\\ \\forall x\\in S,\\ x\\le M$"],"note":"這個 $M$ 是 $S$ 的一個上界。","say":"說精確：存在一個實數 M，集合裡每一個 x 都小於等於它，就說 S 有上界。","board":[{"do":"write","line":"${{e:\\exists M\\in\\mathbb{R}}}\\ {{a:\\forall x\\in S}},\\ x\\le M$"},{"do":"underline","term":"e","on":"存在一個實數","ms":1175},{"do":"underline","term":"a","on":"每一個 x","ms":3250}],"t":[29664,37188]},{"show":["下界：對所有 $x\\in S$，$x\\ge m$"],"say":"下界對稱：每一個元素都大於等於 m。地板和天花板。","board":[{"do":"write","line":"下界：對所有 $x\\in S$，$x\\ge m$"}],"t":[37476,43704]},{"show":["有界：存在 $K>0$，$|x|\\le K$"],"note":"既有上界又有下界。","say":"上下都有界，就叫有界。等價的說法是：所有元素的絕對值都不超過某個正數 K。","board":[{"do":"write","line":"有界：存在 $K>0$，$|x|\\le K$","on":"上下都有界","ms":50}],"t":[43992,52812]},{"show":["函數有界：看值域 $\\{f(x):x\\in A\\}$"],"note":"數列有界：看 $\\{a_n:n\\in\\mathbb{N}\\}$。","say":"函數有界，看的是它在集合 A 上取到的所有值。所以同一個函數，換了定義域，答案可能不同。","board":[{"do":"write","line":"函數有界：看值域 $\\{f(x):x\\in {{da:A}}\\}$"},{"do":"focus","term":"da","label":"定義域","on":"換了定義域","ms":6575}],"t":[53100,62928]}],"check":3},{"title":"改寫成常數減正數","beats":[{"show":["$S=\\{\\frac{3n-1}{n+2}:n\\in\\mathbb{N}\\}$"],"say":"找上界有個好用的手法。看這個集合：分子三 n 減一，分母 n 加二。","board":[{"do":"write","line":"$S=\\left\\{\\frac{3n-1}{n+2}:n\\in\\mathbb{N}\\right\\}$"}],"t":[63216,70776]},{"show":["$\\frac{3n-1}{n+2}=\\frac{3(n+2)-7}{n+2}$"],"say":"分子湊出分母的三倍：三倍的 n 加二，再減七。這樣就能拆開。","board":[{"do":"write","line":"$\\frac{3n-1}{n+2}=\\frac{{{t:3(n+2)}}-7}{n+2}$","on":"分子湊出","ms":50},{"do":"underline","term":"t","on":"三倍的 n","ms":2113}],"t":[71064,78300]},{"show":["為什麼要拆：只剩一個分式要判斷"],"note":"分子分母都有 $n$，直接看不出大小。","say":"為什麼要拆？分子分母都有 n，直接看看不出大小。拆成常數減一個分式，就只剩分式要判斷。","board":[{"do":"write","line":"${{q1:3}}-\\frac{7}{n+2}$"},{"do":"focus","term":"q1","label":"常數","on":"常數"}]},{"show":["$=3-\\frac{7}{n+2}$"],"note":"放大時不必找最好的界，夠用就好。","say":"拆開是三，減掉 n 加二分之七。減掉的那一塊永遠是正的。","board":[{"do":"write","line":"$=3-{{p:\\frac{7}{n+2}}}$"},{"do":"underline","term":"p","label":"永遠是正的","on":"減掉的那一塊"}]},{"show":["分子 = 分母的倍數 + 常數"],"note":"分母是 $n+2$ 這類一次式時都能用。","say":"分母是 n 加二這類一次式，分子都能這樣湊：湊出分母的倍數，剩下一個常數。","board":[{"do":"write","line":"分子 ＝ 分母的倍數 ＋ 常數"}]}],"key":"分子湊出分母的倍數：常數減正數","check":2},{"title":"找一個下界","beats":[{"show":["上界 3：$\\frac{7}{n+2}>0$"],"note":"3 是上界，但不是 $S$ 的元素。","say":"減一個正數一定比三小，所以三是上界。換個方向，每一項最少是多少？","board":[{"do":"write","line":"$3-{{p:\\frac{7}{n+2}}}<3$"},{"do":"focus","term":"p","label":"正的","on":"正數"},{"do":"write","line":"上界是 $3$","on":"所以"}],"t":[85644,93780]},{"show":["$n\\ge1$ ⇒ $n+2\\ge3$"],"note":"$\\frac{7}{n+2}\\le\\frac{7}{3}$。","say":"n 至少是一，分母至少是三，所以減掉的那一塊最多是三分之七。","board":[{"do":"write","line":"$n\\ge1$ ⇒ $n+2\\ge3$"},{"do":"write","line":"$\\frac{7}{n+2}\\le\\frac{7}{3}$","on":"最多"}],"t":[94068,100728]},{"show":["減得越多，項越小"],"note":"要找最小的項，就看減掉的量最多是多少。","say":"減掉的越多，剩下的越少。所以要找最少的那一項，就看減掉的量最大是多少。","board":[{"do":"write","line":"減得越多，項越小"}]}],"predict":{"ask":"每一項至少是多少？","options":[{"label":"$3-\\frac{7}{3}=\\frac{2}{3}$","correct":true},{"label":"$\\frac{7}{3}$","why":"$\\frac{7}{3}$ 是減掉的量最多多少，項本身是 3 減它。"},{"label":"$3$","why":"3 是上界：每一項都比 3 小，不是至少 3。"}]}},{"title":"沒有上界怎麼寫","beats":[{"show":["對每個 $M$，存在 $x\\in S$ 使 $x>M$"],"note":"天花板放多高，總有元素穿過去。","say":"上一題的下界是三分之二，n 等於一時取到。反過來，沒有上界怎麼寫？照否定的規則翻。","board":[{"do":"write","line":"有上界：$\\exists M\\ \\forall x\\in S,\\ x\\le M$"},{"do":"transform","line":"沒有上界：$\\forall M\\ \\exists x\\in S,\\ x>M$","on":"照否定"}],"t":[101016,111168]},{"show":["先給 $M$，再找 $x$"],"note":"$x$ 可以依賴 $M$。","say":"順序很重要：先有人給你 M，你再去找 x，x 可以跟著 M 挑。","board":[{"do":"write","line":"先給 ${{m:M}}$，再找 ${{x:x}}$","tint":{"m":"blue","x":"violet"}},{"do":"focus","term":"m","color":"blue","on":"給你"},{"do":"focus","term":"x","color":"violet","label":"跟著M挑","on":"再去找"}],"t":[111456,117828]},{"show":["$\\{n^2\\}$：取自然數 $n>M$","$n^2\\ge n>M$"],"note":"存在 $n>M$ 要靠〈阿基米德性質〉。","say":"例如 n 平方的集合：給定 M，找一個比 M 大的自然數 n，n 平方又不比 n 小，就穿過去了。","board":[{"do":"clear"},{"do":"write","line":"$\\{n^2\\}$：取自然數 $n>M$","on":"例如"},{"do":"write","line":"$n^2\\ge n>M$","on":"不比"}],"t":[118116,126864]},{"show":["$n\\ge1$，兩邊乘正數 $n$：$n^2\\ge n$"],"note":"乘正數，不等號方向不變。","say":"為什麼 n 平方不小於 n？n 是自然數，至少是一。兩邊同乘正數 n，不等號不變，就得到了。","board":[{"do":"write","line":"$n\\ge1$ ⇒ $n\\cdot n\\ge n\\cdot 1$"}]}],"key":"先給 $M$，再找超過它的 $x$","check":1},{"title":"證明：函數有界","beats":[{"show":["$f(x)=\\frac{x}{1+x^2}$：從平方非負出發"],"say":"策略：要證一加 x 平方分之 x 有界。從一個一定對的不等式出發，整理好再除過去。","board":[{"do":"write","line":"$f(x)=\\frac{x}{1+x^2}$：從平方非負出發"}],"t":[127152,136080]},{"show":["$(|x|-1)^2\\ge0$ ⇒ $2|x|\\le1+x^2$"],"note":"展開 $x^2-2|x|+1\\ge0$。","why":{"ask":"為什麼 $2|x|\\le1+x^2$？","say":"第一步：二倍 x 的絕對值，為什麼不超過一加 x 平方？","options":[{"label":"$(|x|-1)^2\\ge0$ 展開再移項","correct":true},{"label":"$x^2\\ge|x|$ 恆成立","why":"$|x|<1$ 時不對，例如 $x=\\frac{1}{2}$。要每一個 $x$ 都成立，得從平方非負出發。"},{"label":"$x$ 很大時 $x^2$ 遠大於 $2|x|$","why":"只看了 $x$ 很大的時候；有界要每一個 $x$ 都成立，包括 0 附近。"}],"t":[136368,141696]},"say":"x 的絕對值減一，平方不會是負的。展開是 x 平方減二倍絕對值加一，移項就是這一行。","board":[{"do":"write","line":"$(|x|-1)^2\\ge0$ ⇒ $2|x|\\le1+x^2$","on":"第一步","ms":50},{"do":"write","line":"展開：$x^2-2|x|+1\\ge0$","why":true,"on":"展開是","ms":3950}],"t":[141984,151272]},{"show":["把 $-2|x|$ 移到右邊"],"note":"左邊只剩 0。","say":"再把負的二倍絕對值移到右邊，左邊就只剩零。所以二倍絕對值不超過一加 x 平方。","board":[{"do":"write","line":"$1+x^2\\ge 2|x|$"}]},{"show":["除以 $2(1+x^2)$：$\\frac{|x|}{1+x^2}\\le\\frac{1}{2}$"],"say":"一加 x 平方一定是正的，兩邊同除以它的兩倍，不等號方向不變。","board":[{"do":"write","line":"除以 ${{d:2(1+x^2)}}$：$\\frac{|x|}{1+x^2}\\le\\frac{1}{2}$"},{"do":"underline","term":"d","label":"正的","on":"一定是正的"}]},{"show":["$|f(x)|\\le\\frac{1}{2}$ 對所有 $x$ 成立"],"note":"同一個界管住每一個 $x$。","why":{"ask":"為什麼這樣就是有界？","say":"最後一步：為什麼這樣就證完有界了？","options":[{"label":"同一個 $K$ 對所有 $x$ 都成立","correct":true},{"label":"$f(1)=\\frac{1}{2}$ 是最大值","why":"只看了一點；說它是最大值正要靠上一步，而且有界還要管到下面。"},{"label":"$x\\to\\infty$ 時 $f(x)\\to0$","why":"極限只管很遠的地方，中間的 $x$ 沒管到；要的是對每一個 $x$ 的界。"}]},"say":"f 的絕對值不超過二分之一，對每一個實數 x 都成立。同一個 K 管住全部，這就是有界。","board":[{"do":"keep","n":1},{"do":"write","line":"$|f(x)|\\le{{k:\\frac{1}{2}}}$ 對所有 $x$ 成立","on":"最後一步"},{"do":"underline","term":"k","color":"green","label":"同一個 K","why":true,"on":"同一個 K"}]},{"show":["取 $K=\\frac{1}{2}>0$，符合有界定義"],"note":"$K$ 不隨 $x$ 改變。","say":"定義要找一個正數 K。取 K 等於二分之一，它不隨 x 改變，所以每個 x 都被管住。","board":[{"do":"write","line":"取 $K=\\frac{1}{2}>0$，符合有界定義"}]}],"key":"平方非負給出 $2|x|\\le1+x^2$","proof":true,"of":"ex2","skeleton":"直接","where":{"ask":"「$1+x^2>0$」用在哪一步？","steps":[{"label":"$(|x|-1)^2\\ge0$","why":"這只用到平方不會是負的。"},{"label":"移項得 $2|x|\\le1+x^2$","why":"移項是兩邊加減同一個數，不管正負都可以。"},{"label":"兩邊除以 $2(1+x^2)$","correct":true},{"label":"$|f(x)|\\le\\frac{1}{2}$ 對所有 $x$ 成立","why":"這只用到上一步對每一個 $x$ 都成立。"}]}}],"checks":[{"ask":"$S=\\{1-\\frac{1}{n}:n\\in\\mathbb{N}\\}$。下列何者不是 $S$ 的上界？","options":[{"label":"0.99","correct":true},{"label":"1","why":"每項 $1-\\frac{1}{n}<1$，1 是上界。你可能以為上界一定要屬於 $S$。"},{"label":"5","why":"比 1 大的數都是上界；上界不唯一。"}]},{"ask":"「$S$ 沒有下界」的正確寫法是？","options":[{"label":"$\\forall m\\in\\mathbb{R}\\ \\exists x\\in S,x<m$","correct":true},{"label":"$\\exists m\\in\\mathbb{R}\\ \\forall x\\in S,x<m$","why":"那是在說 $S$ 有一個嚴格的上界，跟下界無關；量詞也沒翻。"},{"label":"$\\forall x\\in S\\ \\exists m\\in\\mathbb{R},x<m$","why":"量詞順序反了，$m$ 隨 $x$ 變，取 $m=x+1$ 永遠成立，對任何集合都對。"}]},{"ask":"$\\frac{3n-1}{n+2}$ 改寫成 $3-\\frac{7}{n+2}$ 之後，最直接看出的是？","options":[{"label":"每一項都小於 3","correct":true},{"label":"每一項都大於 3","why":"減去的 $\\frac{7}{n+2}$ 是正數，結果比 3 小，不是比 3 大。"},{"label":"最小的一項是 0","why":"$n=1$ 時是 $3-\\frac{7}{3}=\\frac{2}{3}$，而且 $n$ 越大值越大；最小值是 $\\frac{2}{3}$。"}]},{"ask":"$f(x)=x$ 在 $(0,1)$ 上有界嗎？","options":[{"label":"有界，例如 $|f(x)|\\le1$","correct":true},{"label":"沒有界，因為 $f(x)=x$ 在 $\\mathbb{R}$ 上無界","why":"有界與否要看定義域。限制在 $(0,1)$ 上，值域就是 $(0,1)$。"},{"label":"沒有上界，因為取不到 1","why":"「取不到最大值」跟「沒有上界」是兩回事；1 是上界，只是不在值域裡。"}]}],"practice":[{"id":"an-sup-007","core":true,"note":"先證 3 是上界；它恰好也是最小的上界。"},{"id":"cg-12b-001","core":true},{"id":"cg-12b-003","core":true},{"id":"cg-12b-004","core":true},{"id":"an-sup-005","note":"$x+\\frac{1}{x}\\ge2$：由 $(\\sqrt{x}-\\frac{1}{\\sqrt{x}})^2\\ge0$ 得下界。"},{"id":"cg-12b-002"},{"id":"cg-12b-005"},{"id":"cg-12b-006"},{"id":"cg-12b-007","challenge":true}]},"max-min":{"id":"max-min","prerequisites":["bounds"],"next":["sup-inf"],"related":["extreme-value-theorem","induction"],"objectives":["寫得出最大元的定義：屬於集合，而且是上界。","會證明一個集合有最大元（找到它並驗兩個條件），也會證明沒有最大元。","知道有限非空集合一定有最大元，而無限集合有上界也不一定有。"],"concept":[{"heading":"① 天花板被摸到的時候","body":["上界是天花板。如果集合裡有某個元素剛好頂到天花板，它就是最大元。$(0,1]$ 的最大元是 1；$(0,1)$ 有上界 1，但 1 不在集合裡，而且集合裡任何一個數 $x$，$\\frac{x+1}{2}$ 都比它大一點、仍在集合裡，所以沒有最大元。"]},{"heading":"② 定義","body":["設 $S\\subseteq\\mathbb{R}$。$m$ 是 $S$ 的最大元（記為 $\\max S$），如果 (i) $m\\in S$，而且 (ii) 對所有 $x\\in S$，$x\\le m$。換句話說：$m$ 是屬於 $S$ 的上界。最小元 $\\min S$ 對稱定義。","最大元若存在就唯一：若 $m$、$m'$ 都是最大元，由 (ii) $m\\le m'$ 且 $m'\\le m$，所以 $m=m'$。"],"tex":["m=\\max S\\iff m\\in S\\ \\text{且}\\ \\forall x\\in S,\\ x\\le m"]},{"heading":"③ 什麼時候一定有","body":["有限非空集合一定有最大元（下面折疊段用歸納法證）。無限集合就不一定，即使有上界也不一定：$(0,1)$、$\\{1-\\frac{1}{n}\\}$ 都有上界而沒有最大元。","函數的最大值是值域的最大元。連續函數在閉區間 $[a,b]$ 上一定取得到最大值與最小值，這是〈極值定理〉；拿掉「閉」或「連續」都會失敗，例如 $f(x)=x$ 在 $(0,1)$ 上就取不到。","沒有最大元的時候，仍然可以問「最低的天花板」在哪，那就是下一課的上確界。"]},{"heading":"證明：有限非空集合有最大元","body":["對元素個數 $n$ 做〈數學歸納法〉。$P(n)$：任何恰有 $n$ 個元素的實數集合都有最大元。","基底 $n=1$：$S=\\{a\\}$，$a\\in S$ 且 $a\\le a$，$\\max S=a$。","歸納步驟：設 $P(k)$ 成立。$S$ 有 $k+1$ 個元素，拿出一個元素 $a$，剩下 $T=S\\setminus\\{a\\}$ 有 $k$ 個元素，由歸納假設有最大元 $t$。令 $m$ 為 $a$ 與 $t$ 中較大的那個。$m\\in S$；對 $x\\in T$，$x\\le t\\le m$；對 $x=a$，$x\\le m$。所以 $m=\\max S$，$P(k+1)$ 成立。"],"collapsible":true}],"workedExamples":[{"title":"有最大元，沒有最小元","prompt":"$S=(0,1]$。證明 $\\max S=1$，並證明 $S$ 沒有最小元。","steps":["$\\max$：$1\\in(0,1]$，而且每個 $x\\in(0,1]$ 都滿足 $x\\le1$。兩個條件都成立，$\\max S=1$。","沒有最小元：反設 $m$ 是最小元，則 $0<m\\le1$。令 $x=\\frac{m}{2}$，則 $0<x<m\\le1$，$x\\in S$。","由最小元的定義 $m\\le x=\\frac{m}{2}$，得 $m\\le0$，與 $m>0$ 矛盾。"],"answer":"$\\max S=1$；$S$ 沒有最小元（每個元素的一半都更小且仍在 $S$ 中）"},{"title":"數列集合的最大元","prompt":"$S=\\{\\frac{n}{n^2+4}:n\\in\\mathbb{N}\\}$。求 $\\max S$，並判斷 $S$ 有沒有最小元。","steps":["前三項：$\\frac{1}{5}=0.2$，$\\frac{2}{8}=0.25$，$\\frac{3}{13}\\approx0.231$。猜 $n=2$ 最大，值 $\\frac{1}{4}$。","證明 $\\frac{1}{4}$ 是上界：$\\frac{1}{4}-\\frac{n}{n^2+4}=\\frac{n^2+4-4n}{4(n^2+4)}=\\frac{(n-2)^2}{4(n^2+4)}\\ge0$。又 $\\frac{1}{4}=\\frac{2}{2^2+4}\\in S$，所以 $\\max S=\\frac{1}{4}$。","最小元：每項都 $>0$；而 $n\\ge1$ 時 $\\frac{n}{n^2+4}<\\frac{n}{n^2}=\\frac{1}{n}$，所以對任何正數 $c$，取自然數 $n>\\frac{1}{c}$ 就有一項 $<c$。因此沒有任何元素是最小的（比它小的項一定存在）。"],"answer":"$\\max S=\\frac{1}{4}$（$n=2$）；沒有最小元，$\\inf S=0$ 但取不到"},{"title":"交錯集合的最大與最小","prompt":"$S=\\{(-1)^n(1+\\frac{1}{n}):n\\in\\mathbb{N}\\}$。求 $\\max S$ 與 $\\min S$。","problemId":"an-sup-002","steps":["偶數 $n$：值 $1+\\frac{1}{n}$，$n=2$ 最大，為 $\\frac{3}{2}$；奇數 $n$：值 $-(1+\\frac{1}{n})$，$n=1$ 最小，為 $-2$。","$\\frac{3}{2}\\in S$，且每項 $\\le\\frac{3}{2}$（偶數項 $\\le1+\\frac{1}{2}$，奇數項是負的）。所以 $\\max S=\\frac{3}{2}$。","$-2\\in S$，且每項 $\\ge-2$（奇數項 $\\ge-(1+1)$，偶數項是正的）。所以 $\\min S=-2$。"],"answer":"$\\max S=\\frac{3}{2}$，$\\min S=-2$"}],"pitfalls":["只驗了「是上界」沒驗「屬於集合」，把 $\\sup$ 當成 $\\max$。","以為有上界就有最大元：$(0,1)$ 是反例。","用前幾項猜最大元，沒有證明後面的項都不超過它。","把「沒有最小元」講成「最小元是 0」。0 不在集合裡。"],"voice":"4882d4b9","sections":[{"title":"天花板被摸到","beats":[{"show":["上界被集合裡的元素頂到"],"note":"那個元素就是最大元。","say":"上界是天花板。如果集合裡剛好有一個元素頂到天花板，它就是最大元。","board":[{"do":"write","line":"上界 ＝ 天花板"},{"do":"write","line":"元素頂到天花板 ⇒ 最大元","on":"剛好有"}],"t":[0,7812]},{"show":["上界 $m$：每個 $x\\in S$ 都 $x\\le m$"],"note":"$m$ 自己也在 $S$ 裡，就是最大元。","say":"上界 m：集合裡每個 x 都小於等於 m。如果 m 自己也在集合裡，就是最大元。","board":[{"do":"write","line":"$m$ 是上界：每個 $x\\in S$，$x\\le m$"},{"do":"write","line":"$m\\in S$ ⇒ $m=\\max S$","on":"自己也"}]},{"show":["$(0,1]$ 的最大元是 1"],"say":"零到一、右邊包含一：一在集合裡，而且沒有人比它大，所以最大元是一。","board":[{"do":"clear"},{"do":"write","line":"$(0,1]$","on":"零到一"},{"do":"write","line":"$1\\in(0,1]$","on":"一在集合裡"},{"do":"write","line":"每個 $x\\le1$","on":"沒有人比它大"},{"do":"write","line":"$\\max\\,(0,1]=1$","color":"green","on":"所以最大元"}]},{"show":["$(0,1)$：上界 1，但 1 不在集合裡"],"note":"任何 $x$，$\\frac{x+1}{2}$ 都比它大一點、仍在集合裡。","say":"把右端點挖掉，一還是上界，可是它不在集合裡了。任何一個元素，跟一的中點都比它大，還在集合裡。","board":[{"do":"clear"},{"do":"write","line":"$(0,1)$","on":"把右端點挖掉"},{"do":"write","line":"$1$ 是上界，但 $1\\notin(0,1)$","on":"一還是上界"},{"do":"write","line":"$x\\in(0,1)$ ⇒ ${{c:\\frac{x+1}{2}}}>x$，仍在集合裡","on":"任何一個元素"},{"do":"focus","term":"c","color":"gold","label":"中點","on":"中點"}]}],"check":0},{"title":"定義","beats":[{"show":["(i) $m\\in S$","(ii) 對所有 $x\\in S$，$x\\le m$"],"note":"$m$ 是屬於 $S$ 的上界。","say":"最大元要兩件事一起成立：第一，它在集合裡；第二，集合裡每一個數都不超過它。","board":[{"do":"write","line":"$m=\\max S$"},{"do":"write","line":"(i) ${{a:m\\in S}}$","on":"第一"},{"do":"write","line":"(ii) 對所有 $x\\in S$，${{b:x\\le m}}$","on":"第二"}],"t":[26892,35172]},{"show":["最小元 $\\min S$ 對稱定義"],"say":"最小元一樣：在集合裡，而且每一個數都大於等於它。","board":[{"do":"clear"},{"do":"write","line":"$m=\\min S$","on":"最小元"},{"do":"write","line":"(i) $m\\in S$","on":"在集合裡"},{"do":"write","line":"(ii) 對所有 $x\\in S$，$x\\ge m$","on":"大於等於"}],"t":[35460,41004]},{"show":["最大元若存在就唯一"],"note":"$m\\le m'$ 且 $m'\\le m$，所以 $m=m'$。","say":"最大元如果有，只會有一個。兩個都是最大元，就互相小於等於，只能相等。","board":[{"do":"clear"},{"do":"write","line":"$m,\\ m'$ 都是 $\\max S$","on":"兩個都是"},{"do":"write","line":"$m\\le m'$ 且 $m'\\le m$","on":"互相小於等於"},{"do":"write","line":"⇒ ${{e:m=m'}}$","color":"green","on":"只能"}],"t":[41292,49824]}],"check":3},{"title":"什麼時候一定有","beats":[{"show":["有限非空集合：一定有最大元"],"note":"用歸納法證，證明在下一節。","say":"有限個數，一定挑得出最大的，這可以用歸納法證，下一節就證。","board":[{"do":"write","line":"有限非空集合 ⇒ 一定有最大元"},{"do":"write","line":"證法：歸納法","on":"歸納法"}],"t":[50112,56700]},{"show":["無限集合：有上界也不一定"],"note":"$(0,1)$、$\\{1-\\frac{1}{n}\\}$ 都沒有最大元。","say":"無限集合就不一定了。就算有上界，天花板也可能永遠摸不到。","board":[{"do":"write","line":"無限集合：有上界，不一定有最大元"},{"do":"write","line":"例：$(0,1)$","on":"天花板也可能"}],"t":[56988,64044]},{"show":["連續：圖形不斷開；閉區間含兩端點"],"say":"連續，直覺上是圖形一筆畫過去、不斷開。閉區間，是兩個端點都算進來。","board":[{"do":"write","line":"連續：圖形一筆畫過去、不斷開"},{"do":"write","line":"閉區間 $[a,b]$：含兩端點","on":"閉區間"}]},{"show":["連續函數在閉區間 $[a,b]$ 取得到最大值"],"note":"$f(x)=x$ 在 $(0,1)$ 上就取不到。","say":"函數的最大值，就是值域的最大元。連續函數在閉區間上一定取得到，拿掉閉或連續就會失敗。","board":[{"do":"clear"},{"do":"write","line":"最大值 ＝ 值域的最大元","on":"函數的最大值"},{"do":"write","line":"$f$ 連續，$[a,b]$ 閉 ⇒ 取得到最大值","on":"連續函數"},{"do":"write","line":"$f(x)=x$ 在 $(0,1)$ 取不到","on":"拿掉閉"}]},{"show":["$f(x)=x$ 在 $(0,1)$：到 1 是空心點"],"say":"畫出來：f x 等於 x 往右上爬，到一的地方是空心點，高度一永遠碰不到。","board":[{"do":"plot","graph":{"window":[-0.5,1.5,-0.5,1.5],"curves":[{"expr":"x","domain":[0,1],"color":"blue"}],"points":[{"x":1,"y":1,"open":true}]}}]}],"check":1},{"title":"證明：有限集有最大元","beats":[{"show":["對元素個數 $n$ 做歸納"],"note":"$P(n)$：恰有 $n$ 個元素的實數集合都有最大元。","say":"策略：對元素個數做數學歸納法。P n 說：任何恰有 n 個元素的實數集合，都有最大元。","board":[{"do":"write","line":"對元素個數 $n$ 做歸納"}],"t":[74700,84456]},{"show":["基底 $n=1$：$S=\\{a\\}$，$\\max S=a$"],"note":"$a\\in S$ 且 $a\\le a$。","say":"基底：只有一個元素 a，a 在 S 裡，而且 a 小於等於 a，所以最大元就是 a。","board":[{"do":"write","line":"基底：$S=\\{a\\}$，$\\max S=a$"}],"t":[84744,92412]},{"show":["$S$ 有 $k+1$ 個元素：拿出 $a$","$T=S\\setminus\\{a\\}$ 有最大元 $t$"],"note":"$T$ 有 $k$ 個元素，用歸納假設。","say":"歸納步驟：S 有 k 加一個元素，先拿出一個 a。剩下的 T 有 k 個元素，由歸納假設有最大元 t。","board":[{"do":"keep","n":1},{"do":"write","line":"$S$ 有 $k+1$ 個元素：拿出 ${{a:a}}$","tint":{"a":"violet"},"on":"先拿出","ms":2900},{"do":"write","line":"$T=S\\setminus\\{a\\}$ 有最大元 ${{t:t}}$","tint":{"t":"blue"},"on":"剩下的","ms":4813}],"t":[92700,102492]},{"show":["歸納假設：$k$ 個元素的集合有最大元"],"say":"歸納假設：先假設 k 個元素的集合都有最大元，T 才有最大元 t。像 k 是一，T 只有一個數，它自己就是 t。","board":[{"do":"write","line":"歸納假設：$k$ 個元素的集合有最大元","on":"歸納假設"}]},{"show":["令 $m$ 為 $a$ 與 $t$ 中較大的那個"],"note":"兩個數一定比得出大小。","say":"a 和 t 兩個數比一比，取較大的那個，叫它 m。m 是 a 或 t，所以在 S 裡。","board":[{"do":"keep","n":2},{"do":"write","line":"${{m:m}}=$ ${{a:a}}$ 與 ${{t:t}}$ 中較大的","on":"比一比"}]},{"show":["$x\\in T$：$x\\le t\\le m$；$x=a$：$x\\le m$"],"note":"$m\\in S$ 又是上界，所以 $m=\\max S$。","why":{"ask":"為什麼 $T$ 裡的 $x$ 都 $\\le m$？","say":"T 裡面的每一個元素，為什麼都不超過 m？","options":[{"label":"$x\\le t$（$t$ 是 $T$ 的最大元），而 $t\\le m$","correct":true},{"label":"$x\\le a$","why":"$a$ 只是隨手拿出來的那一個，不一定比 $T$ 裡的元素大。"},{"label":"$x\\in S$，所以 $x\\le\\max S$","why":"$\\max S$ 存在正是要證的東西，不能先拿來用。"}]},"say":"T 裡的 x 不超過 T 的最大元 t，t 又不超過 m。a 也不超過 m。m 在 S 裡又是上界，就是最大元。","board":[{"do":"keep","n":2},{"do":"write","line":"$x\\in T$：$x\\le {{t:t}}\\le {{m:m}}$","on":"每一個元素"},{"do":"focus","term":"t","why":true,"on":"T 的最大元"},{"do":"write","line":"$x={{a:a}}$：$x\\le m$ ⇒ ${{mx:m=\\max S}}$","why":true,"on":"a 也不超過"},{"do":"box","term":"mx","color":"green","why":true,"on":"m 在 S 裡"}]}],"key":"拿出一個 $a$，剩下的最大值再跟 $a$ 比","proof":true,"of":3,"skeleton":"歸納","where":{"ask":"歸納假設 $P(k)$ 用在哪一步？","steps":[{"label":"基底：$\\{a\\}$ 的最大元是 $a$","why":"基底只看單一元素的集合，還沒有歸納假設。"},{"label":"$T=S\\setminus\\{a\\}$ 有最大元 $t$","correct":true},{"label":"取 $a$ 與 $t$ 中較大的 $m$","why":"這只用到兩個實數一定比得出大小。"},{"label":"驗 $m=\\max S$","why":"這一步只用到 $t$ 是 $T$ 的最大元和 $m$ 的取法。"}]}},{"title":"有最大，沒最小","beats":[{"show":["$S=(0,1]$：$\\max S=1$"],"note":"$1\\in S$，而且每個 $x\\le1$。","say":"回到零到一包含一。一在集合裡，每個元素都不超過它，兩件事都成立，最大元是一。","board":[{"do":"write","line":"$S=(0,1]$"},{"do":"write","line":"$1\\in S$","on":"一在集合裡"},{"do":"write","line":"每個 $x\\in S$，$x\\le1$","on":"不超過它"},{"do":"write","line":"$\\max S=1$","color":"green","on":"兩件事都成立"}],"t":[126216,135504]},{"show":["沒有最小元？反設 $m$ 是最小元"],"note":"$0<m\\le1$。","say":"那最小元呢？反設 m 是最小元，m 大於零。只要找到集合裡比 m 更小的數，就矛盾了。","board":[{"do":"clear"},{"do":"write","line":"反設 $m$ 是最小元","on":"反設"},{"do":"write","line":"$0<m\\le1$","on":"大於零"},{"do":"write","line":"找 $x\\in S$，$x<m$ ⇒ 矛盾","on":"只要找到"}],"t":[135792,145620]},{"show":["反證法：假設反面，推出矛盾"],"note":"$m\\in(0,1]$，所以 $m>0$。","say":"這叫反證法：先假設結論的反面，推出矛盾，反面就不可能。m 在零到一裡，所以 m 一定大於零。","board":[{"do":"write","line":"反證：假設反面 ⇒ 矛盾"},{"do":"write","line":"$m\\in S=(0,1]$ ⇒ $m>0$","on":"m 在"}]}],"predict":{"ask":"拿哪個 $x$ 打掉 $m$？","options":[{"label":"$x=\\frac{m}{2}$：$0<x<m$，仍在 $S$ 裡","correct":true},{"label":"$x=0$","why":"0 比 $m$ 小，但 $0\\notin(0,1]$，最小元的性質只管集合裡的數。"},{"label":"$x=m-1$","why":"$m\\le1$，所以 $m-1\\le0$，不在 $S$ 裡，比了沒有用。"}]}},{"title":"先猜最大元","beats":[{"show":["$S=\\{\\frac{n}{n^2+4}:n\\in\\mathbb{N}\\}$"],"say":"換一個數列集合：分子 n，分母 n 平方加四。最大元是哪一項？","board":[{"do":"write","line":"$S=\\{\\frac{n}{n^2+4}:n\\in\\mathbb{N}\\}$"},{"do":"write","line":"找最大的一項","on":"最大元"}],"t":[145908,153252]},{"show":["$\\frac{1}{5}=0.2$，$\\frac{2}{8}=0.25$，$\\frac{3}{13}\\approx0.231$"],"say":"先算前三項：零點二、零點二五、大約零點二三一。先升後降，第二項看起來最大。","board":[{"do":"clear"},{"do":"write","line":"$n=1$：$\\frac{1}{5}=0.2$","on":"先算前三項"},{"do":"write","line":"$n=2$：$\\frac{2}{8}=0.25$","on":"零點二五"},{"do":"write","line":"$n=3$：$\\frac{3}{13}\\approx0.231$","on":"大約"},{"do":"write","line":"先升後降","on":"先升後降"}],"t":[153540,163188]}],"check":2},{"title":"證明猜對了","beats":[{"show":["猜 $\\max S=\\frac{1}{4}$（$n=2$）"],"note":"用前幾項猜，一定要證後面都不超過它。","say":"猜最大元是四分之一。但只看前三項不算數，要證明每一項都不超過四分之一。","board":[{"do":"write","line":"猜 $\\max S=\\frac{1}{4}$"},{"do":"write","line":"要證：每個 $n$，$\\frac{n}{n^2+4}\\le\\frac{1}{4}$","on":"要證明"}],"t":[163476,171900]},{"show":["$\\frac{1}{4}-\\frac{n}{n^2+4}=\\frac{?}{4(n^2+4)}$"],"say":"直接相減，通分。分母是四倍的 n 平方加四，分子會是一個很好看的式子。","board":[{"do":"write","line":"$\\frac{1}{4}-\\frac{n}{n^2+4}=\\frac{?}{{{p:4(n^2+4)}}}$"},{"do":"underline","term":"p","label":"分母","on":"分母是"}],"t":[172188,180144]},{"show":["通分：兩項都換成同一個分母"],"say":"通分的做法：兩項都改成分母四倍的 n 平方加四，分子各乘上補的那個因子，再相減。","board":[{"do":"write","line":"兩項都換成分母 $4(n^2+4)$"},{"do":"write","line":"分子各乘補的因子，再相減","on":"分子各"}]}],"key":"相減通分，證明差永遠 $\\ge0$","predict":{"ask":"分子是？","options":[{"label":"$n^2+4-4n=(n-2)^2\\ge0$","correct":true},{"label":"$n^2-4$","why":"$\\frac{n}{n^2+4}$ 通分要乘 4，分子減的是 $4n$，不是 4；而且 $n^2-4$ 在 $n=1$ 是負的。"},{"label":"$(n+2)^2$","why":"中間那項是減 $4n$，配方是 $(n-2)^2$；$(n+2)^2$ 的中間項是加 $4n$。"}]}}],"checks":[{"ask":"$(0,1)$ 有最大元嗎？","options":[{"label":"沒有：對任何 $x\\in(0,1)$，$\\frac{x+1}{2}\\in(0,1)$ 而且比 $x$ 大","correct":true},{"label":"有，是 1","why":"1 是上界，但 $1\\notin(0,1)$，不符合最大元的第一個條件。"},{"label":"有，是 0.999…","why":"$0.999\\dots=1$，跟上一個選項是同一個數，不在開區間裡。"}]},{"ask":"下列哪個集合一定有最大元？","options":[{"label":"$\\{3,-1,7,2\\}$","correct":true},{"label":"$\\{1-\\frac{1}{n}:n\\in\\mathbb{N}\\}$","why":"有上界 1 但取不到；無限集合有上界不保證有最大元。"},{"label":"$\\{x:x^2<4\\}$","why":"這是 $(-2,2)$，開區間沒有最大元。"}]},{"ask":"$S=\\{\\frac{n}{n^2+4}:n\\in\\mathbb{N}\\}$ 的最大元是？","options":[{"label":"$\\frac{1}{4}$","correct":true},{"label":"$\\frac{1}{5}$","why":"那是 $n=1$ 的項；$n=2$ 時 $\\frac{2}{8}=\\frac{1}{4}$ 更大。"},{"label":"0","why":"0 是下確界（項越來越小往 0 靠），跟最大元無關，而且 0 不在 $S$ 裡。"}]},{"ask":"要證 $m=\\max S$，要驗哪兩件事？","options":[{"label":"$m\\in S$，且對所有 $x\\in S$ 有 $x\\le m$","correct":true},{"label":"$m$ 是上界，且對每個 $\\varepsilon>0$ 有 $x\\in S$ 使 $x>m-\\varepsilon$","why":"那是上確界的條件；它不要求 $m\\in S$，證不出最大元。"},{"label":"$m\\in S$，且 $m$ 比前幾項都大","why":"只比前幾項大不夠，要對 $S$ 的每個元素都 $\\le m$。"}]}],"practice":[{"id":"an-sup-006","core":true,"note":"這題的上確界取得到，就是最大元。"},{"id":"an-sup-002","core":true},{"id":"cg-12b-008","core":true},{"id":"cg-12b-010","core":true},{"id":"an-sup-005","note":"$x+\\frac{1}{x}$ 在 $x=1$ 取到最小值 2。"},{"id":"cg-12b-009"}]},"sup-inf":{"id":"sup-inf","prerequisites":["bounds","max-min"],"next":["completeness-axiom"],"related":["archimedean-property"],"objectives":["說得出上確界的定義：最小的上界，而且它不一定屬於集合。","會用 $\\varepsilon$ 判準證明某個數就是 $\\sup S$：它是上界，而且任何比它小一點的數都不是上界。","分得清 $\\sup$ 與 $\\max$：$\\max$ 存在時兩者相等；$\\max$ 不存在時 $\\sup$ 仍可能存在。"],"concept":[{"heading":"① 沒有最大元，但有一個「天花板」","body":["$S=\\{1-\\frac{1}{n}:n\\in\\mathbb{N}\\}=\\{0,\\frac{1}{2},\\frac{2}{3},\\frac{3}{4},\\dots\\}$。每一項都小於 1，所以 1 是 $S$ 的上界；2、10 也都是上界。","$S$ 沒有最大元：任何一項 $1-\\frac{1}{n}$，下一項 $1-\\frac{1}{n+1}$ 都比它大。但所有上界裡有一個最小的，就是 1。這個「最小的上界」叫做 $S$ 的上確界，寫成 $\\sup S$。"]},{"heading":"② 定義","body":["設 $S\\subseteq\\mathbb{R}$ 非空。實數 $s$ 叫做 $S$ 的上確界（最小上界），如果：(i) $s$ 是 $S$ 的上界，也就是對所有 $x\\in S$，$x\\le s$；(ii) 若 $b$ 是 $S$ 的任一上界，則 $s\\le b$。","下確界 $\\inf S$ 對稱地定義：最大的下界。由 (ii)，上確界若存在就唯一：兩個都是最小上界，就互相 $\\le$，所以相等。"]},{"heading":"③ 實際在用的版本：$\\varepsilon$ 判準","body":["條件 (ii) 很難直接檢查，因為上界有無限多個。等價的說法是：$s=\\sup S$ 若且唯若 (i) $s$ 是上界，而且 (ii′) 對每一個 $\\varepsilon>0$，都存在 $x\\in S$ 使得 $x>s-\\varepsilon$。","人話：$s$ 往下退任何一點點，就不再是上界了。注意量詞順序：先給 $\\varepsilon$，再找 $x$；不同的 $\\varepsilon$ 可以找不同的 $x$。"],"tex":["s=\\sup S\\iff\\begin{cases}\\forall x\\in S,\\ x\\le s\\\\ \\forall\\varepsilon>0\\ \\exists x\\in S,\\ x>s-\\varepsilon\\end{cases}"]},{"heading":"證明：(ii) 與 (ii′) 等價","body":["(ii) $\\Rightarrow$ (ii′)：給定 $\\varepsilon>0$。$s-\\varepsilon<s$，由 (ii)，$s-\\varepsilon$ 不可能是上界（否則 $s\\le s-\\varepsilon$）。「不是上界」的意思正是：存在 $x\\in S$ 使 $x>s-\\varepsilon$。","(ii′) $\\Rightarrow$ (ii)：設 $b$ 是上界，要證 $s\\le b$。反設 $b<s$，取 $\\varepsilon=s-b>0$。由 (ii′) 有 $x\\in S$ 使 $x>s-\\varepsilon=b$，與 $b$ 是上界矛盾。所以 $s\\le b$。"],"collapsible":true},{"heading":"④ $\\sup$ 與 $\\max$ 的關係","body":["如果 $S$ 有最大元 $m$，那麼 $\\sup S=m$：$m$ 是上界，而且任何上界 $b$ 都 $\\ge m$（因為 $m\\in S$）。反過來，$\\sup S$ 屬於 $S$ 時它就是最大元。","所以 $\\sup$ 是 $\\max$ 的推廣：$\\max$ 只在「天花板剛好被摸到」時存在，$\\sup$ 只要 $S$ 非空、有上界就存在——這件事不是證出來的，而是實數的公理，見〈完備性公理〉。"]}],"workedExamples":[{"title":"證明 $\\sup\\{1-\\frac{1}{n}\\}=1$","prompt":"$S=\\{1-\\frac{1}{n}:n\\in\\mathbb{N}\\}$，證明 $\\sup S=1$，並說明 1 不在 $S$ 裡。","problemId":"an-sup-001","steps":["(i) 上界：對每個 $n\\in\\mathbb{N}$，$\\frac{1}{n}>0$，所以 $1-\\frac{1}{n}<1$。","(ii′) 給定 $\\varepsilon>0$。要找 $n$ 使 $1-\\frac{1}{n}>1-\\varepsilon$，也就是 $\\frac{1}{n}<\\varepsilon$，也就是 $n>\\frac{1}{\\varepsilon}$。由阿基米德性質，這樣的自然數 $n$ 存在。","具體一次：$\\varepsilon=0.01$ 時要 $n>100$，取 $n=101$，$1-\\frac{1}{101}\\approx0.990099>0.99$。","$1\\notin S$：$1-\\frac{1}{n}=1$ 會推出 $\\frac{1}{n}=0$，沒有自然數做得到。"],"answer":"$\\sup S=1$，而且取不到（$S$ 沒有最大元）","note":"步驟 2 用到「$n$ 可以比任何實數大」，這就是〈阿基米德性質〉；它看似顯然，其實要靠完備性證。"},{"title":"交錯的集合：上下確界都取得到","prompt":"$S=\\{(-1)^n(1+\\frac{1}{n}):n\\in\\mathbb{N}\\}$，求 $\\sup S$ 與 $\\inf S$。","problemId":"an-sup-002","steps":["先列幾項：$n=1,2,3,4,5,6$ 得 $-2,\\frac{3}{2},-\\frac{4}{3},\\frac{5}{4},-\\frac{6}{5},\\frac{7}{6}$。偶數項為正、遞減；奇數項為負、遞增。","偶數 $n$ 時值是 $1+\\frac{1}{n}\\le1+\\frac{1}{2}=\\frac{3}{2}$；奇數 $n$ 時值是負的，也 $<\\frac{3}{2}$。所以 $\\frac{3}{2}$ 是上界，而且 $n=2$ 時取到，是最大元，$\\sup S=\\frac{3}{2}$。","奇數 $n$ 時值是 $-(1+\\frac{1}{n})\\ge-(1+1)=-2$；偶數 $n$ 時值是正的，也 $>-2$。所以 $-2$ 是下界，而且 $n=1$ 時取到，$\\inf S=-2$。"],"answer":"$\\sup S=\\frac{3}{2}$，$\\inf S=-2$（都取得到）","note":"有最大元時不必用 $\\varepsilon$ 判準：最大元自動是上確界（觀念 ④）。"},{"title":"先增後減的數列","prompt":"$S=\\{\\frac{n}{2^n}:n\\in\\mathbb{N}\\}$，求 $\\sup S$。","problemId":"an-sup-006","steps":["前幾項：$\\frac{1}{2},\\frac{2}{4}=\\frac{1}{2},\\frac{3}{8},\\frac{4}{16}=\\frac{1}{4},\\dots$。","比較相鄰兩項：$\\frac{a_{n+1}}{a_n}=\\frac{n+1}{2n}$。$n=1$ 時等於 1，$n\\ge2$ 時 $\\frac{n+1}{2n}\\le\\frac{3}{4}<1$。所以 $a_1=a_2$，之後嚴格遞減。","最大元是 $a_1=a_2=\\frac{1}{2}$，所以 $\\sup S=\\frac{1}{2}$。"],"answer":"$\\frac{1}{2}$"}],"pitfalls":["以為 $\\sup S$ 一定屬於 $S$。$\\sup\\{1-\\frac{1}{n}\\}=1$ 就不在 $S$ 裡。","只證了「$s$ 是上界」就宣稱 $s=\\sup S$。10 也是 $\\{1-\\frac{1}{n}\\}$ 的上界，最小性 (ii′) 一定要證。","$\\varepsilon$ 判準的量詞寫反：「存在 $x$，對所有 $\\varepsilon$，$x>s-\\varepsilon$」會逼出 $x\\ge s$，那是 $\\max$ 不是 $\\sup$。","把「沒有上界」的集合寫 $\\sup S=\\infty$ 卻當成一個實數來運算。$\\infty$ 只是記號，表示沒有上界。"],"voice":"f7a66b82","sections":[{"title":"最低的天花板","beats":[{"show":["$S=\\{0,\\frac{1}{2},\\frac{2}{3},\\frac{3}{4},\\dots\\}$"],"note":"$1-\\frac{1}{n}$：每一項都小於 1。","say":"一減 n 分之一：零、二分之一、三分之二，一直往上爬，每一項都比一小。","board":[{"do":"write","line":"$S=\\{0,\\ \\frac{1}{2},\\ \\frac{2}{3},\\ \\dots\\}$"},{"do":"write","line":"$1-\\frac{1}{n}<1$","on":"每一項"}],"t":[0,7740]},{"show":["點越爬越高，貼近 1"],"note":"橫軸是 $n$，縱軸是 $1-\\frac{1}{n}$。","say":"畫出來：每一項是一個點，往右一直爬，卻永遠碰不到虛線一。","board":[{"do":"plot","graph":{"window":[0,9,-0.2,1.3],"points":[{"x":1,"y":0},{"x":2,"y":0.5},{"x":3,"y":0.6667},{"x":4,"y":0.75},{"x":5,"y":0.8},{"x":6,"y":0.8333},{"x":7,"y":0.8571},{"x":8,"y":0.875}],"dashed":[[[0,1],[9,1]]],"labels":[{"x":0.2,"y":1.1,"text":"1","anchor":"start"}]}}]},{"show":["上界：1、2、10 都是"],"note":"沒有最大元：下一項總是更大。","say":"一、二、十都是上界。可是這個集合沒有最大元，任何一項的下一項都比它大。","board":[{"do":"write","line":"上界：1、2、10 都是"},{"do":"write","line":"沒有最大元","on":"沒有最大元"}]},{"show":["所有上界裡最小的：1"],"note":"記成 $\\sup S$，上確界。","say":"雖然摸不到天花板，但所有上界裡有一個最低的，就是一。這個最小的上界叫上確界。","board":[{"do":"clear"},{"do":"write","line":"最小的上界 ＝ ${{m:1}}$","on":"所有上界"},{"do":"box","term":"m","color":"green","on":"就是一"},{"do":"write","line":"$\\sup S$：上確界","on":"這個最小"}]}],"check":0},{"title":"定義與判準","beats":[{"show":["(i) $s$ 是上界","(ii) 任一上界 $b$ 都有 $s\\le b$"],"say":"上確界的定義兩條：它是上界；而且任何上界都不比它小。下確界對稱，是最大的下界。","board":[{"do":"write","line":"(i) $s$ 是上界"},{"do":"write","line":"(ii) 任一上界 $b$ 都有 ${{ii:s\\le b}}$","on":"任何上界"},{"do":"write","line":"下確界：最大的下界","on":"下確界"}],"t":[26136,35784]},{"show":["(ii) 很難直接查"],"note":"上界有無限多個。","say":"第二條很難直接檢查，因為上界有無限多個，總不能一個一個比。","board":[{"do":"underline","term":"ii","label":"上界太多"}],"t":[36072,42336]},{"show":["(ii′) $\\forall\\varepsilon>0\\ \\exists x\\in S,\\ x>s-\\varepsilon$"],"say":"實際用的是等價的版本：對每一個 epsilon，都找得到集合裡的 x，比 s 減 epsilon 還大。","board":[{"do":"clear"},{"do":"write","line":"(ii′) $\\forall\\varepsilon>0\\ \\exists x\\in S,\\ {{ex:x>s-\\varepsilon}}$","on":"對每一個"},{"do":"underline","term":"ex","on":"比 s 減"}],"t":[42624,50544]},{"show":["$s$ 往下退一點點，就不再是上界"],"note":"先給 $\\varepsilon$，再找 $x$。","say":"翻成人話：s 往下退任何一點點，就有元素穿過去。先給 epsilon，再找 x。兩者等價，下一節證明。","board":[{"do":"write","line":"$s$ 往下退，就有 $x$ 穿過去"},{"do":"write","line":"先給 $\\varepsilon$，再找 $x$","on":"先給"}],"t":[50832,62100]}],"check":1},{"title":"證明：兩個版本等價","beats":[{"show":["(ii) ⇒ (ii′) 直接證；(ii′) ⇒ (ii) 反證"],"note":"兩個方向都假設 (i)：$s$ 是上界。","say":"策略：兩個方向分開證。從二推二撇直接證；從二撇推二用反證，假設有比 s 小的上界。","board":[{"do":"write","line":"(ii) ⇒ (ii′)：直接證","on":"從二推二撇","ms":3213},{"do":"write","line":"(ii′) ⇒ (ii)：反證","on":"從二撇推二","ms":5088}],"t":[62388,72000]},{"show":["$s-\\varepsilon<s$，所以 $s-\\varepsilon$ 不是上界"],"note":"否則由 (ii)，$s\\le s-\\varepsilon$。","why":{"ask":"為什麼 $s-\\varepsilon$ 不是上界？","say":"給定 epsilon。s 減 epsilon 為什麼不可能是上界？","options":[{"label":"由 (ii)，上界都 $\\ge s$，而 $s-\\varepsilon<s$","correct":true},{"label":"$s-\\varepsilon$ 在 $S$ 裡","why":"$s-\\varepsilon$ 不一定在 $S$ 裡；它不是上界，是因為它比 $s$ 小。"},{"label":"$\\varepsilon$ 很小","why":"$\\varepsilon$ 多大都對；關鍵是 $s-\\varepsilon<s$，而每個上界都 $\\ge s$。"}],"t":[72288,77472]},"say":"第二條說每個上界都不比 s 小。s 減 epsilon 比 s 小，所以它不是上界。","board":[{"do":"write","line":"$s-\\varepsilon<s$ ⇒ ${{nb:s-\\varepsilon}}$ 不是上界","on":"s 減 epsilon","ms":1713},{"do":"underline","term":"nb","label":"由 (ii)","why":true,"on":"第二條說","ms":50}],"t":[77760,85464]},{"show":["若 $s-\\varepsilon$ 是上界，由 (ii)：","$s\\le s-\\varepsilon$"],"note":"但 $\\varepsilon>0$，這不可能。","say":"假設 s 減 epsilon 是上界，由第二條得 s 小於等於 s 減 epsilon。但 epsilon 是正的，所以不可能。","board":[{"do":"write","line":"假設 $s-\\varepsilon$ 是上界"},{"do":"write","line":"(ii) ⇒ ${{n1:s\\le s-\\varepsilon}}$","on":"第二條"},{"do":"strike","term":"n1","label":"矛盾","on":"正的"}]},{"show":["不是上界：有 $x\\in S$，$x>s-\\varepsilon$"],"note":"這正是 (ii′)。","say":"不是上界的意思，就是集合裡有某個 x 穿過它，比 s 減 epsilon 大。這就是二撇。","board":[{"do":"write","line":"${{ex:\\exists x\\in S,\\ x>s-\\varepsilon}}$","on":"集合裡有"},{"do":"box","term":"ex","color":"green","label":"(ii′)","on":"這就是"}]},{"show":["反過來：設上界 $b<s$，取 $\\varepsilon=s-b>0$"],"note":"讓 $s-\\varepsilon$ 剛好等於 $b$。","why":{"ask":"為什麼取 $\\varepsilon=s-b$？","say":"反方向：假設有上界 b 比 s 小。epsilon 為什麼要取 s 減 b？","options":[{"label":"讓 $s-\\varepsilon$ 剛好等於 $b$","correct":true},{"label":"$\\varepsilon$ 越小越好","why":"越小不一定有用；要剛好讓 $s-\\varepsilon=b$，穿過去的 $x$ 才會比 $b$ 大。"},{"label":"任何 $\\varepsilon>0$ 都可以","why":"隨便取只得到 $x>s-\\varepsilon$，不一定 $>b$；取 $s-b$ 才剛好碰到 $b$。"}]},"say":"取 epsilon 等於 s 減 b，它是正的，而且 s 減 epsilon 剛好是 b。","board":[{"do":"clear"},{"do":"write","line":"反設上界 $b<s$","on":"假設有上界"},{"do":"write","line":"取 ${{e:\\varepsilon=s-b}}>0$","on":"epsilon 為什麼"},{"do":"write","line":"$s-\\varepsilon=b$","why":true,"on":"而且 s 減"}]},{"show":["由 (ii′)：有 $x\\in S$，$x>b$","與 $b$ 是上界矛盾，所以 $s\\le b$"],"say":"二撇給出集合裡的 x 比 b 大，跟 b 是上界矛盾。所以每個上界都不比 s 小，這就是第二條。","board":[{"do":"keep","n":2},{"do":"write","line":"(ii′)：$\\exists x\\in S,\\ x>b$","on":"二撇給出"},{"do":"write","line":"與 $b$ 是上界矛盾 ⇒ $\\;{{fin:s\\le b}}$","on":"跟 b 是上界矛盾"},{"do":"box","term":"fin","color":"green","on":"所以每個上界"}]}],"key":"反設上界 $b<s$，取 $\\varepsilon=s-b$","proof":true,"of":3,"skeleton":"反證","order":{"ask":"把 (ii′) ⇒ (ii) 排回順序：依序點每一步","steps":[{"label":"設 $b$ 是上界，反設 $b<s$"},{"label":"取 $\\varepsilon=s-b>0$","why":"要先有 $b$，而且知道 $b<s$，才取得出正的 $\\varepsilon$。"},{"label":"由 (ii′)，有 $x\\in S$，$x>s-\\varepsilon=b$","why":"(ii′) 要先給定 $\\varepsilon$ 才能用。"},{"label":"與 $b$ 是上界矛盾，所以 $s\\le b$","why":"要先找到穿過 $b$ 的 $x$，才有矛盾。"}]}},{"title":"證 $\\sup S=1$","beats":[{"show":["(i) $\\frac{1}{n}>0$ ⇒ $1-\\frac{1}{n}<1$"],"say":"先證一是上界：n 分之一是正的，一減掉它一定小於一。","board":[{"do":"write","line":"(i) ${{p:\\frac{1}{n}>0}}$ ⇒ $1-\\frac{1}{n}<1$"},{"do":"underline","term":"p","on":"是正的"}],"t":[116892,122724]},{"show":["(ii′) 要 $1-\\frac{1}{n}>1-\\varepsilon$"],"note":"也就是 $\\frac{1}{n}<\\varepsilon$，即 $n>\\frac{1}{\\varepsilon}$。","say":"再證退一點點就失守：給定 epsilon，要找 n 讓 n 分之一小於 epsilon，n 只要比 epsilon 分之一大。","board":[{"do":"write","line":"(ii′) $1-\\frac{1}{n}>1-\\varepsilon$"},{"do":"transform","line":"$\\frac{1}{n}<\\varepsilon$","on":"n 分之一小於"},{"do":"write","line":"$n>\\frac{1}{\\varepsilon}$","on":"n 只要"}],"t":[123012,131508]},{"show":["這樣的自然數存在"],"note":"靠〈阿基米德性質〉。","say":"比任何實數都大的自然數一定找得到，這要靠阿基米德性質。具體試一個 epsilon。","board":[{"do":"clear"},{"do":"write","line":"自然數 $n>\\frac{1}{\\varepsilon}$ 存在","on":"比任何"},{"do":"write","line":"靠〈阿基米德性質〉","on":"阿基米德性質"}],"t":[131796,140148]},{"show":["阿基米德性質：","任意實數 $r$，都有自然數 $n>r$"],"note":"取 $r=\\frac{1}{\\varepsilon}$。","say":"阿基米德性質說：對任何實數 r，都有自然數 n 大於 r。把 r 取成 epsilon 分之一，就有 n 大於它。","board":[{"do":"write","line":"${{ar:\\forall r\\in\\mathbb{R}\\ \\exists n\\in\\mathbb{N},\\ n>r}}$"},{"do":"write","line":"取 $r=\\frac{1}{\\varepsilon}$ ⇒ $n>\\frac{1}{\\varepsilon}$","on":"取成"}]},{"show":["直覺：自然數一個接一個，沒有盡頭"],"note":"嚴格版：$\\mathbb{N}$ 有上界會矛盾，靠完備性。","say":"為什麼一定有？直覺是自然數一個一個加一，沒有盡頭。嚴格要靠完備性：自然數若有上界，就會矛盾。","board":[{"do":"write","line":"若 $\\mathbb{N}$ 有上界 ⇒ 矛盾","on":"自然數若"}]}],"check":3},{"title":"$\\sup$ 與 $\\max$","beats":[{"show":["$1\\notin S$"],"note":"$1-\\frac{1}{n}=1$ 會推出 $\\frac{1}{n}=0$。","say":"還有，一不在集合裡：一減 n 分之一要等於一，n 分之一就得是零，做不到。","board":[{"do":"write","line":"$1\\notin S$"},{"do":"write","line":"$1-\\frac{1}{n}=1$ ⇒ $\\frac{1}{n}=0$","on":"一減 n","ms":2213}],"t":[140436,147888]},{"show":["有最大元 $m$ ⇒ $\\sup S=m$"],"note":"$\\sup S\\in S$ 時，它就是最大元。","say":"如果集合有最大元，最大元自動就是上確界。上確界是最大元的推廣。","board":[{"do":"write","line":"有最大元 $m$ ⇒ $\\sup S=m$","on":"如果集合","ms":50}],"t":[148176,156024]},{"show":["$S=\\{(-1)^n(1+\\frac{1}{n})\\}$"],"note":"$-2,\\frac{3}{2},-\\frac{4}{3},\\frac{5}{4},\\dots$","say":"看一個正負交錯的集合：負二、二分之三、負三分之四、四分之五。偶數項是正的，奇數項是負的。","board":[{"do":"clear"},{"do":"write","line":"$S=\\{(-1)^n(1+\\frac{1}{n})\\}$","on":"正負交錯","ms":538},{"do":"write","line":"$-2,\\ {{t:\\frac{3}{2}}},\\ -\\frac{4}{3},\\ \\frac{5}{4},\\ \\dots$","on":"負二","ms":2163}],"t":[156312,167184]},{"show":["$\\sup S=\\frac{3}{2}$（$n=2$ 取到）"],"note":"取得到，就不必用 $\\varepsilon$ 判準。","say":"偶數項最大是 n 等於二的二分之三，負的更不用說，所以上確界二分之三，而且取得到。下確界呢？","board":[{"do":"underline","term":"t","on":"n 等於二的","ms":1213},{"do":"write","line":"$\\sup S={{t:\\frac{3}{2}}}$（$n=2$ 取到）","on":"所以上確界","ms":4613}],"t":[167472,177876]}],"check":2},{"title":"先增後減","beats":[{"show":["$S=\\{\\frac{n}{2^n}\\}$"],"note":"$\\frac{1}{2},\\frac{1}{2},\\frac{3}{8},\\frac{1}{4},\\dots$","say":"最後一個：二的 n 次方分之 n。前幾項二分之一、二分之一、八分之三、四分之一，好像在變小。","board":[{"do":"write","line":"$S=\\{\\frac{n}{2^n}\\}$"},{"do":"write","line":"$\\frac{1}{2},\\ \\frac{1}{2},\\ \\frac{3}{8},\\ \\frac{1}{4},\\ \\dots$","on":"前幾項"}],"t":[178164,188676]},{"show":["比較相鄰兩項：$\\frac{a_{n+1}}{a_n}$"],"say":"要確定，就拿後一項除以前一項，看比值有沒有小於一。","board":[{"do":"write","line":"後一項 ÷ 前一項"},{"do":"write","line":"$\\frac{a_{n+1}}{a_n}<1\\ ?$","on":"比值"}],"t":[188964,194832]},{"show":["比值 $<1$：後一項較小，遞減","遞減：最大的在最前面"],"note":"最大元就是上確界（觀念 ④）。","say":"如果比值小於一，後一項就比前一項小，數列遞減。最大的一項就在最前面，上確界就是它。","board":[{"do":"write","line":"比值 $<1$ ⇒ 後一項較小，遞減"},{"do":"write","line":"最大元在最前面 ⇒ $\\sup$ ＝ 最大元","on":"最大的"}]}],"key":"相鄰比跟 1 比大小，找出轉折點","predict":{"ask":"$\\frac{a_{n+1}}{a_n}$ 是？","options":[{"label":"$\\frac{n+1}{2n}$","correct":true},{"label":"$\\frac{n+1}{n}$","why":"分母 $2^{n+1}$ 比 $2^n$ 多一個 2，相除留下 $\\frac{1}{2}$，你漏了。"},{"label":"$\\frac{2(n+1)}{n}$","why":"$\\frac{2^n}{2^{n+1}}=\\frac{1}{2}$，2 在分母，你乘反了。"}]}}],"checks":[{"ask":"$S=\\{1-\\frac{1}{n}:n\\in\\mathbb{N}\\}$。下列何者正確？","options":[{"label":"$\\sup S=1$，但 $S$ 沒有最大元","correct":true},{"label":"$\\sup S=1$，而且 1 是 $S$ 的最大元","why":"你把 $\\sup$ 當成一定取得到。$1-\\frac{1}{n}=1$ 沒有自然數解，1 不在 $S$ 裡。"},{"label":"$S$ 沒有上確界，因為沒有最大元","why":"你把 $\\sup$ 跟 $\\max$ 混成一件事。沒有最大元，最小上界 1 仍然存在。"}]},{"ask":"要證 $s=\\sup S$，除了「$s$ 是上界」，還要證哪一件？","options":[{"label":"對每個 $\\varepsilon>0$，存在 $x\\in S$ 使 $x>s-\\varepsilon$","correct":true},{"label":"存在 $x\\in S$，使 $x>s-\\varepsilon$ 對每個 $\\varepsilon>0$ 都成立","why":"量詞順序寫反了。同一個 $x$ 要對所有 $\\varepsilon$ 都成立，等於 $x\\ge s$，那是在證 $s$ 是最大元。"},{"label":"$s\\in S$","why":"那是最大元的條件。上確界可以不屬於 $S$，例如 $\\sup\\{1-\\frac{1}{n}\\}=1$。"}]},{"ask":"$S=\\{(-1)^n(1+\\frac{1}{n}):n\\in\\mathbb{N}\\}$。$\\inf S$ 是？","options":[{"label":"$-2$","correct":true},{"label":"$-1$","why":"你看的是 $n\\to\\infty$ 時奇數項的去向（$-1$）。但 $n=1$ 這一項 $-2$ 比它更小，下確界要看整個集合。"},{"label":"1","why":"1 是偶數項往下靠近的值，跟下確界無關；奇數項全是負的。"}]},{"ask":"$\\varepsilon=0.01$ 時，要讓 $1-\\frac{1}{n}>1-\\varepsilon$，$n$ 至少要多大？","options":[{"label":"$n>100$，例如 $n=101$","correct":true},{"label":"$n>10$","why":"你可能解成 $\\frac{1}{n^2}<\\varepsilon$。這裡是 $\\frac{1}{n}<0.01$，要 $n>100$。"},{"label":"$n=100$ 就夠","why":"$n=100$ 時 $\\frac{1}{n}=0.01$，不是嚴格小於 $\\varepsilon$；要 $n>100$。"}]}],"practice":[{"id":"an-sup-001","core":true},{"id":"an-sup-002","core":true},{"id":"an-sup-006","core":true},{"id":"an-sup-007","core":true},{"id":"cg-12b-011","core":true},{"id":"cg-12b-014","core":true},{"id":"an-sup-005"},{"id":"cg-12b-012"},{"id":"cg-12b-013"},{"id":"cg-12b-015"},{"id":"an-sup-008","challenge":true,"note":"挑戰：$n^{1/n}$ 先增後減，比較 $n=2$ 與 $n=3$。"},{"id":"an-sup-004","challenge":true,"note":"挑戰：$(1+\\frac{1}{n})^n$ 遞增，上確界是極限 $e$，取不到。"}]},"completeness-axiom":{"id":"completeness-axiom","prerequisites":["sup-inf"],"next":["archimedean-property"],"related":["contradiction","monotone-convergence-proof","cauchy-sequence","bolzano-weierstrass"],"objectives":["寫出完備性公理：$\\mathbb{R}$ 的每個非空、有上界的子集都有上確界，而且上確界是實數。","說明 $\\mathbb{Q}$ 為什麼不滿足這條公理，並說得出「非空」「有上界」各自為什麼不能拿掉。","由上確界的版本推出下確界的版本。"],"concept":[{"heading":"① 有理數有洞","body":["有理數很密：任兩個有理數之間還有有理數。但它有洞：$\\{x\\in\\mathbb{Q}:x^2<2\\}$ 在 $\\mathbb{Q}$ 裡有上界（例如 2），卻找不到最小的上界——任何有理數上界都可以再往左挪（範例 2）。最小的上界本來應該是 $\\sqrt{2}$，但 $\\sqrt{2}$ 不是有理數（〈反證法〉）。","微積分裡「數列往某處擠，那個地方就是極限」的直覺，正是依賴「沒有洞」。實數就是把這些洞補起來的數系，而「沒有洞」寫成精確的語言，就是完備性公理。"]},{"heading":"② 公理","body":["$\\mathbb{R}$ 的每一個非空、有上界的子集 $S$，都有上確界 $\\sup S$，而且 $\\sup S\\in\\mathbb{R}$。","這是公理，不是定理：它跟加減乘除、大小順序的規則一起，刻畫出實數。$\\mathbb{Q}$ 滿足其他所有規則，唯獨不滿足這一條。"],"tex":["\\varnothing\\ne S\\subseteq\\mathbb{R},\\ S\\text{ 有上界}\\ \\Longrightarrow\\ \\sup S\\text{ 存在且}\\in\\mathbb{R}"]},{"heading":"③ 兩個條件都不能拿掉","body":["非空：空集合沒有元素，每個實數都是它的上界，上界裡沒有最小的。","有上界：$\\mathbb{N}$ 沒有上界（〈阿基米德性質〉），自然不會有最小上界。習慣上寫 $\\sup\\mathbb{N}=\\infty$，但 $\\infty$ 不是實數。"]},{"heading":"④ 公理怎麼用","body":["要證明「某個數存在」（$\\sqrt{2}$、數列的極限、函數取到最大值的那個點），標準手法是三步：先造一個集合，讓你要的數「應該是它的上確界」；再檢查這個集合非空、有上界，由公理得到 $s=\\sup S$；最後用上確界的兩個條件——$s$ 是上界，而且任何比 $s$ 小的數都不是上界——證明 $s$ 就是你要的那個數。範例 2 的論證，在 $\\mathbb{R}$ 裡就是這樣證出 $\\sqrt{2}$ 存在的。"]},{"heading":"預告：完備性有很多張臉","body":["在 $\\mathbb{R}$ 上，下面幾句互相等價，任何一句都可以當作完備性公理：最小上界性質（本課）；有界單調數列收斂（〈單調收斂定理（嚴格版）〉）；Cauchy 數列收斂（〈Cauchy 數列〉，需再加上阿基米德性質）；有界數列有收斂子數列（〈Bolzano–Weierstrass〉）。這一章接下來的定理，全部都是從本課這條公理推出來的。"],"collapsible":true}],"workedExamples":[{"title":"下確界也一定存在","prompt":"證明：$\\mathbb{R}$ 的每個非空、有下界的子集 $S$ 都有下確界，而且 $\\inf S=-\\sup(-S)$，其中 $-S=\\{-x:x\\in S\\}$。","steps":["$S$ 有下界 $m$：對所有 $x\\in S$，$x\\ge m$，所以 $-x\\le-m$。$-S$ 非空、有上界 $-m$，由完備性公理 $s=\\sup(-S)$ 存在。","$-s$ 是 $S$ 的下界：對 $x\\in S$，$-x\\le s$，所以 $x\\ge-s$。","$-s$ 是最大的下界：若 $b$ 是 $S$ 的下界，則 $-b$ 是 $-S$ 的上界，由 $s$ 是最小上界得 $s\\le-b$，即 $b\\le-s$。","所以 $\\inf S=-s=-\\sup(-S)$。例：$\\inf\\{\\frac{1}{n}\\}=-\\sup\\{-\\frac{1}{n}\\}=-0=0$。"],"answer":"$\\inf S=-\\sup(-S)$"},{"title":"在 $\\mathbb{Q}$ 裡找不到最小上界","prompt":"$S=\\{x\\in\\mathbb{Q}:x^2<2\\}$。證明沒有有理數 $s$ 是 $S$ 的最小上界。","steps":["反設有理數 $s$ 是 $S$ 的最小上界。$1\\in S$，所以 $s\\ge1>0$。$s^2=2$ 不可能（$\\sqrt{2}$ 無理），所以 $s^2<2$ 或 $s^2>2$。","若 $s^2<2$：取有理數 $h$，$0<h\\le\\min(\\frac{1}{2},\\frac{2-s^2}{2(2s+1)})$。因為 $0<h<1$，$h^2<h$，所以 $(s+h)^2=s^2+2sh+h^2<s^2+h(2s+1)\\le s^2+\\frac{2-s^2}{2}<2$。於是 $s+h\\in S$ 而且大於 $s$，與 $s$ 是上界矛盾。例：$s=1.4$ 時 $\\frac{2-s^2}{2(2s+1)}\\approx0.00526$，取 $h=0.005$，$1.405^2=1.974025<2$。","若 $s^2>2$：取有理數 $h=\\frac{s^2-2}{2s}>0$，則 $s-h=\\frac{s^2+2}{2s}>0$，而且 $(s-h)^2=s^2-2sh+h^2>s^2-(s^2-2)=2$。任一 $x\\in S$：$x\\le0$ 時 $x<s-h$；$x>0$ 時若 $x>s-h$ 則 $x^2>(s-h)^2>2$，不可能。所以 $s-h$ 是更小的上界，矛盾。例：$s=\\frac{3}{2}$ 時 $s-h=\\frac{17}{12}$，$(\\frac{17}{12})^2\\approx2.0069>2$。","兩種情況都矛盾，故 $S$ 在 $\\mathbb{Q}$ 中沒有最小上界。"],"answer":"任何有理數上界 $s$ 要嘛可以往右推（$s^2<2$ 時 $s$ 根本不是上界），要嘛可以往左挪（$s^2>2$）","note":"同一個論證在 $\\mathbb{R}$ 裡說明：$s=\\sup\\{x\\in\\mathbb{R}:x^2<2\\}$ 只能滿足 $s^2=2$。$\\sqrt{2}$ 的存在就是這樣從完備性得來的。"},{"title":"在 $\\mathbb{R}$ 裡的上確界","prompt":"$S=\\{x\\in\\mathbb{Q}:x^2<3\\}$。把 $S$ 看成 $\\mathbb{R}$ 的子集，求 $\\sup S$。","problemId":"an-sup-003","steps":["$S$ 非空（$0\\in S$）、有上界（2：$x\\ge2$ 時 $x^2\\ge4>3$），由完備性公理 $\\sup S$ 存在。","$\\sqrt{3}$ 是上界：$x>\\sqrt{3}>0$ 時 $x^2>3$，不在 $S$。","$\\sqrt{3}$ 是最小的：對每個 $\\varepsilon>0$，區間 $(\\sqrt{3}-\\varepsilon,\\sqrt{3})$ 裡有有理數 $x$（有理數的稠密性，見〈阿基米德性質〉），取 $x>0$ 即有 $x^2<3$，$x\\in S$ 且 $x>\\sqrt{3}-\\varepsilon$。例：$1.73\\in S$，$1.73^2=2.9929<3$；$1.74^2=3.0276>3$。"],"answer":"$\\sup S=\\sqrt{3}$（在 $\\mathbb{R}$ 中存在，但不是有理數）"}],"pitfalls":["忘了「非空」與「有上界」兩個條件，說「每個集合都有上確界」。","以為完備性是可以從有理數證出來的定理。它是實數的公理；$\\mathbb{Q}$ 不滿足它。","以為 $\\sup S$ 一定跟 $S$ 的元素同一類（$S\\subseteq\\mathbb{Q}\\Rightarrow\\sup S\\in\\mathbb{Q}$）。$\\sup\\{x\\in\\mathbb{Q}:x^2<3\\}=\\sqrt{3}$。","下確界另外當成一條公理。它可以由上確界的版本推出（範例 1）。"],"voice":"112b1854","sections":[{"title":"有理數有洞","beats":[{"show":["有理數很密"],"note":"任兩個有理數之間還有有理數。","say":"有理數很密，任兩個之間都還塞得下有理數。可是密，不代表沒有洞。","board":[{"do":"write","line":"有理數很密：$\\frac{a+b}{2}$ 在 $a$、$b$ 之間"},{"do":"write","line":"密 ≠ 沒有洞","color":"gold","on":"不代表"}],"t":[0,7704]},{"show":["$\\{x\\in\\mathbb{Q}:x^2<2\\}$：上界 2"],"note":"卻找不到最小的有理數上界。","say":"看平方小於二的有理數。二是一個上界，可是在有理數裡，找不到最小的上界。","board":[{"do":"write","line":"$S=\\{x\\in\\mathbb{Q}:x^2<2\\}$"},{"do":"write","line":"${{u:2}}$ 是上界，找不到最小的","on":"二是"},{"do":"circle","term":"u","on":"找不到"}],"t":[7992,16416]},{"show":["該是 $\\sqrt{2}$，但它不是有理數"],"say":"最小的上界本來應該是根號二，偏偏它不是有理數。那個位置在有理數線上是個洞。","board":[{"do":"clear"},{"do":"write","line":"最小上界該是 $\\sqrt{2}$","on":"最小的上界"},{"do":"write","line":"${{r:\\sqrt{2}}}\\notin\\mathbb{Q}$","on":"偏偏"},{"do":"underline","term":"r","label":"洞","on":"那個位置"}],"t":[16704,25488]},{"show":["$x^2<2$ 的那一段，往右擠向 $\\sqrt{2}$"],"say":"畫成圖：x 平方低於二的那一段，往右擠向根號二，那一點就是洞。","board":[{"do":"plot","graph":{"window":[0,2,0,3],"curves":[{"expr":"x^2","domain":[0,2],"color":"blue"}],"dashed":[[[0,2],[2,2]],[[1.4142,0],[1.4142,2]]],"points":[{"x":1.4142,"y":2,"open":true}],"labels":[{"x":1.5,"y":0.3,"text":"√2","anchor":"start"}]}}]},{"show":["實數 = 把洞補起來"],"note":"「沒有洞」寫成精確的話，就是完備性公理。","say":"數列往某處擠、那裡就是極限，這個直覺靠的就是沒有洞。實數就是把洞補起來的數系。","board":[{"do":"write","line":"數列擠向某處 ⇒ 極限在那裡"},{"do":"write","line":"實數 ＝ 把洞補起來的數系","color":"green","on":"實數就是"}]}],"check":1},{"title":"公理","beats":[{"show":["非空、有上界的 $S\\subseteq\\mathbb{R}$","⇒ $\\sup S$ 存在且在 $\\mathbb{R}$ 裡"],"say":"完備性公理：實數裡每一個非空、有上界的集合，都有上確界，而且上確界是實數。","board":[{"do":"write","line":"$S\\subseteq\\mathbb{R}$，非空、有上界"},{"do":"write","line":"⇒ ${{b:\\sup S}}\\in\\mathbb{R}$ 存在","on":"都有上確界"},{"do":"box","term":"b","color":"green","on":"而且"}],"t":[35424,43776]},{"show":["是公理，不是定理"],"note":"$\\mathbb{Q}$ 滿足其他規則，唯獨不滿足這一條。","say":"這一條不是證出來的，是拿來刻畫實數的規則。有理數其他規則都滿足，就差這一條。","board":[{"do":"clear"},{"do":"write","line":"公理：規定，不是證明","on":"不是證出來"},{"do":"write","line":"$\\mathbb{Q}$：其他規則都滿足，缺這一條","on":"有理數其他規則"}],"t":[44064,53172]},{"show":["非空：空集合每個數都是上界"],"say":"兩個條件都不能拿掉。空集合沒有元素，每個實數都是它的上界，上界裡沒有最小的。","board":[{"do":"clear"},{"do":"write","line":"非空：空集合的上界 ＝ 所有實數","on":"空集合"},{"do":"write","line":"上界裡沒有最小的","on":"上界裡"}],"t":[53460,62460]},{"show":["有上界：$\\mathbb{N}$ 沒有上界"],"note":"$\\sup\\mathbb{N}=\\infty$ 只是記號，$\\infty$ 不是實數。","say":"自然數沒有上界，當然也沒有最小上界。寫上確界等於無限大，只是記號。","board":[{"do":"write","line":"有上界：$\\mathbb{N}$ 沒有上界"},{"do":"write","line":"$\\sup\\mathbb{N}={{i:\\infty}}$ 只是記號","on":"寫上確界"},{"do":"underline","term":"i","label":"不是實數","on":"無限大"}],"t":[62748,71028]}],"check":0},{"title":"下確界也存在","beats":[{"show":["$S$ 有下界 $m$ ⇒ $-S$ 有上界 $-m$"],"note":"$-S=\\{-x:x\\in S\\}$。","say":"下確界不用另外一條公理。把集合每個數取負號，下界就翻成上界。","board":[{"do":"write","line":"$-S=\\{-x:x\\in S\\}$"},{"do":"write","line":"$S$ 有下界 $m$ ⇒ $-S$ 有上界 $-m$","on":"就翻成"}],"t":[71316,78912]},{"show":["$s=\\sup(-S)$ 存在"],"note":"由完備性公理。","say":"翻過去的集合非空、有上界，公理給我們它的上確界 s。","board":[{"do":"write","line":"${{s:s}}=\\sup(-S)$ 存在","tint":{"s":"violet"}},{"do":"focus","term":"s","color":"violet","label":"公理給的","on":"公理"}],"t":[79200,84960]},{"show":["$-s$ 是 $S$ 最大的下界"],"say":"再翻回來：負 s 是原集合的下界，而且任何下界都不比它大。","board":[{"do":"clear"},{"do":"write","line":"${{n:-s}}$ 是 $S$ 的下界","on":"負 s"},{"do":"write","line":"任何下界 $\\le -s$","on":"而且"},{"do":"box","term":"n","color":"green","label":"最大下界","on":"任何下界"}],"t":[85248,91584]},{"show":["$m$ 是 $S$ 的下界 ⇒ $-m$ 是 $-S$ 的上界","$-m\\ge s$，即 $m\\le-s$"],"note":"$s$ 是 $-S$ 的最小上界。","say":"任取 S 的下界 m，負 m 是翻過去集合的上界。s 是最小上界，所以負 m 大於等於 s，m 就小於等於負 s。","board":[{"do":"write","line":"$m$ 是 $S$ 的下界 ⇒ $-m$ 是 $-S$ 的上界"},{"do":"write","line":"$-m\\ge s$，即 $m\\le-s$","on":"所以"}]},{"show":["例：$\\inf\\{\\frac{1}{n}\\}=-\\sup\\{-\\frac{1}{n}\\}=0$"],"say":"例如 n 分之一的下確界：取負號之後上確界是零，翻回來還是零。","board":[{"do":"clear"},{"do":"write","line":"$\\sup\\{-\\frac{1}{n}\\}=0$","on":"上確界是零"},{"do":"write","line":"$\\inf\\{\\frac{1}{n}\\}=0$","color":"green","on":"翻回來"}]}],"check":2},{"title":"證明：$\\mathbb{Q}$ 裡挪得動","beats":[{"show":["反設有理數 $s$ 是最小上界"],"note":"$s^2=2$ 不可能，剩 $s^2<2$ 或 $s^2>2$。","say":"策略：反證。設有理數 s 是最小上界，它的平方不會剛好是二。分小於二、大於二，各推出矛盾。","board":[{"do":"write","line":"反設：有理數 ${{s:s}}=\\sup S$","tint":{"s":"violet"}},{"do":"write","line":"$s^2\\ne 2$ ⇒ $s^2<2$ 或 $s^2>2$","on":"它的平方","ms":4538}],"t":[99036,110412]},{"show":["$s^2<2$：取有理數 $0<h\\le\\frac{1}{2}$ 夠小","$(s+h)^2<s^2+h(2s+1)<2$"],"note":"$h^2<h$，且 $h\\le\\frac{2-s^2}{2(2s+1)}$。","why":{"ask":"為什麼 $(s+h)^2<2$？","say":"平方小於二的情況：往右推 h，平方為什麼還小於二？","options":[{"label":"$h<1$ 讓 $h^2<h$，增加量被 $h$ 的上限管住","correct":true},{"label":"$h$ 很小，$(s+h)^2$ 幾乎等於 $s^2$","why":"幾乎等於不夠：要確定增加量小於 $2-s^2$，$h$ 得照這個差來挑。"},{"label":"$s+h$ 是有理數","why":"有理數只說它有資格進 $S$；進不進得去，要看平方是不是小於 2。"}],"t":[110700,116352]},"say":"h 小於一，h 平方小於 h，平方的增加量小於 h 乘二 s 加一，h 又照差距挑過，所以還小於二。","board":[{"do":"write","line":"$s^2<2$：取 $0<h\\le\\frac{1}{2}$ 夠小"},{"do":"write","line":"$(s+h)^2<s^2+{{inc:h(2s+1)}}<2$","on":"平方為什麼","ms":3025},{"do":"underline","term":"inc","label":"h² < h","why":true,"on":"h 平方小於 h","ms":1125}],"t":[116640,126180]},{"show":["$s+h\\in S$，而且 $s+h>s$"],"say":"於是 s 加 h 在集合裡，又比 s 大，s 根本不是上界，矛盾。例如一點四零五，平方還小於二。","board":[{"do":"keep","n":2},{"do":"write","line":"$s+h\\in S$，而且 $s+h>s$","on":"於是","ms":50},{"do":"transform","line":"$s+h\\in S$，而且 $s+h>s$ ⇒ ${{s:s}}$ 不是上界","on":"根本不是","ms":3375}],"t":[126468,136620]},{"show":["$s^2>2$：取 $h=\\frac{s^2-2}{2s}>0$","$(s-h)^2>s^2-2sh=2$"],"note":"$S$ 的元素追不過 $s-h$。","why":{"ask":"為什麼 $s-h$ 還是上界？","say":"平方大於二的情況：往左挪到 s 減 h，為什麼還是上界？","options":[{"label":"$(s-h)^2>2$，比 $s-h$ 大的正數平方都 $>2$","correct":true},{"label":"$s-h<s$，而 $s$ 是上界","why":"比上界小的數不一定是上界；要另外說沒有元素超過它。"},{"label":"$h$ 很小，挪一點沒關係","why":"挪太多就不是上界了（像 $\\frac{4}{3}$）；要靠 $(s-h)^2>2$ 才說得準。"}],"t":[136908,142812]},"say":"s 減 h 的平方大於二。集合裡的正數平方都小於二，不可能超過 s 減 h，所以它還是上界。","board":[{"do":"clear"},{"do":"write","line":"$s^2>2$：取 $h=\\frac{s^2-2}{2s}>0$","on":"平方大於二","ms":50},{"do":"write","line":"${{sq:(s-h)^2}}>s^2-2sh=2$","on":"往左挪","ms":1950},{"do":"write","line":"$S$ 的元素追不過 ${{sm:s-h}}$","why":true,"on":"集合裡","ms":2750}],"t":[143100,152712]},{"show":["$s-h=\\frac{s^2+2}{2s}>0$","$x\\in S,\\ x>s-h$ ⇒ $x^2>(s-h)^2>2$"],"say":"s 減 h 是二 s 分之 s 平方加二，是正數，所以能平方。若 x 在集合裡又大於它，x 平方就大於二，矛盾。","board":[{"do":"write","line":"$s-h=\\frac{s^2+2}{2s}>0$"},{"do":"write","line":"$x\\in S,\\ x>s-h$ ⇒ $x^2>(s-h)^2>2$","on":"若 x"}]},{"show":["$s-h<s$ 是更小的上界：矛盾"],"note":"兩種情況都矛盾。","say":"s 減 h 比 s 小，又是上界，s 就不是最小的，矛盾。兩種情況都矛盾，證完。","board":[{"do":"keep","n":1},{"do":"write","line":"${{sm:s-h}}<{{s:s}}$ 是更小的上界：矛盾","on":"又是上界"},{"do":"write","line":"兩種情況都矛盾，證完","color":"green","on":"兩種情況"}]}],"key":"往上或往下挪一點 $h$，打敗最小上界","proof":true,"of":"ex1","skeleton":"反證","predict":{"ask":"$s=\\frac{3}{2}$ 可以往左挪到哪個更小的上界？","options":[{"label":"$\\frac{17}{12}$：$(\\frac{17}{12})^2\\approx2.0069>2$","correct":true},{"label":"$\\frac{4}{3}$","why":"$(\\frac{4}{3})^2$ 小於 2，挪過頭了，$\\frac{4}{3}$ 已經不是上界。"},{"label":"$1.4$","why":"$1.4^2$ 小於 2，比它大的有理數還在集合裡，1.4 不是上界。"}]}},{"title":"在 $\\mathbb{R}$ 裡就有","beats":[{"show":["$S=\\{x\\in\\mathbb{Q}:x^2<3\\}$ 看成 $\\mathbb{R}$ 的子集"],"say":"換一個：平方小於三的有理數，這次放在實數裡看。","board":[{"do":"write","line":"$S=\\{x\\in\\mathbb{Q}:x^2<3\\}$"},{"do":"write","line":"看成 $\\mathbb{R}$ 的子集","on":"實數裡"}],"t":[162144,167724]},{"show":["非空（$0\\in S$）、有上界（2）"],"note":"$x\\ge2$ 時 $x^2\\ge4>3$。","say":"零在裡面，二是上界，因為二的平方是四，比三大。公理保證上確界存在。","board":[{"do":"clear"},{"do":"write","line":"$0\\in S$，上界 ${{u:2}}$：$2^2=4>3$","on":"零在裡面"},{"do":"circle","term":"u","on":"二是上界"},{"do":"write","line":"公理 ⇒ $\\sup S$ 存在","on":"公理保證"}],"t":[168012,176544]},{"show":["$1.73^2=2.9929<3$","$1.74^2=3.0276>3$"],"say":"一點七三的平方比三小，一點七四的平方比三大。上確界夾在這中間，而且不必是有理數。","board":[{"do":"clear"},{"do":"write","line":"$1.73^2=2.9929<3$","on":"一點七三"},{"do":"write","line":"$1.74^2=3.0276>3$","on":"一點七四"},{"do":"write","line":"$1.73<\\sup S<1.74$","on":"夾在這中間"}],"t":[176832,186408]},{"show":["$1.73\\in S$ ⇒ $\\sup S\\ge1.73$","$x^2<3<1.74^2$ ⇒ 1.74 是上界"],"note":"所以 $\\sup S\\le1.74$。","say":"一點七三在 S 裡，所以上確界不小於它。每個 x 平方小於三，比一點七四平方小，所以一點七四是上界。","board":[{"do":"write","line":"$1.73\\in S$ ⇒ $\\sup S\\ge1.73$"},{"do":"write","line":"$x^2<3<1.74^2$ ⇒ 1.74 是上界","on":"平方小於三"}]}],"check":3}],"checks":[{"ask":"完備性公理保證哪一種集合有上確界？","options":[{"label":"$\\mathbb{R}$ 的非空、有上界的子集","correct":true},{"label":"$\\mathbb{R}$ 的任何子集","why":"空集合與 $\\mathbb{N}$ 都沒有實數上確界；兩個條件缺一不可。"},{"label":"$\\mathbb{R}$ 的有限子集","why":"有限集合本來就有最大元，不需要公理；公理的威力在無限集合。"}]},{"ask":"為什麼 $\\mathbb{Q}$ 不滿足完備性？","options":[{"label":"$\\{x\\in\\mathbb{Q}:x^2<2\\}$ 非空、有上界，卻沒有有理數最小上界","correct":true},{"label":"因為 $\\mathbb{Q}$ 沒有上界","why":"$\\mathbb{R}$ 也沒有上界。公理講的是有上界的子集，跟整個數系有沒有上界無關。"},{"label":"因為兩個有理數之間沒有有理數","why":"剛好相反，有理數很密：$a$、$b$ 之間有 $\\frac{a+b}{2}$。$\\mathbb{Q}$ 的問題是有洞，不是不密。"}]},{"ask":"$S$ 非空、有下界。$\\inf S$ 等於？","options":[{"label":"$-\\sup(-S)$","correct":true},{"label":"$\\sup(-S)$","why":"少了一個負號。$-S$ 的最小上界是 $S$ 的最大下界再取負。"},{"label":"$-\\inf(-S)$","why":"$-S$ 的下確界對應的是 $S$ 的上確界：$-\\inf(-S)=\\sup S$。"}]},{"ask":"$S=\\{x\\in\\mathbb{Q}:x^2<3\\}$，$\\sup S$ 是？","options":[{"label":"$\\sqrt{3}$","correct":true},{"label":"不存在，因為 $\\sqrt{3}$ 不是有理數","why":"這裡把 $S$ 看成 $\\mathbb{R}$ 的子集，上確界可以是無理數；只有限定在 $\\mathbb{Q}$ 裡找時才不存在。"},{"label":"1.73","why":"$1.73\\in S$ 但 1.731 也在 $S$ 裡，1.73 連上界都不是。"}]}],"practice":[{"id":"an-sup-003","core":true},{"id":"cg-12b-016","core":true},{"id":"cg-12b-019","core":true},{"id":"cg-12b-021","core":true},{"id":"cg-12b-017"},{"id":"cg-12b-018"},{"id":"cg-12b-020"},{"id":"cg-12b-022"}]},"archimedean-property":{"id":"archimedean-property","prerequisites":["completeness-axiom"],"next":["epsilon-n-definition"],"related":["sup-inf"],"objectives":["寫出阿基米德性質的兩種形式：$n>x$，以及 $\\frac{1}{n}<\\varepsilon$。","用完備性公理證明 $\\mathbb{N}$ 沒有上界。","給定 $\\varepsilon$，算出一個具體的 $n$；並用阿基米德性質在兩個實數之間找出有理數。"],"concept":[{"heading":"① 沒有無限大，也沒有無限小","body":["不管 $x$ 多大，總有自然數比它大；不管 $\\varepsilon$ 多小（只要是正的），總有 $\\frac{1}{n}$ 比它小。聽起來理所當然，但它是之後每一個 $\\varepsilon$-$N$ 證明的最後一步：「取 $N>\\frac{1}{\\varepsilon}$」之所以合法，靠的就是這一條。","它不是白送的：存在一些有序的數系，裡面有比所有自然數都大的元素。在 $\\mathbb{R}$ 裡它成立，理由是完備性。"]},{"heading":"② 敘述","body":["阿基米德性質：對每一個實數 $x$，存在 $n\\in\\mathbb{N}$ 使 $n>x$。也就是說 $\\mathbb{N}$ 在 $\\mathbb{R}$ 中沒有上界。","等價形式：對每一個 $\\varepsilon>0$，存在 $n\\in\\mathbb{N}$ 使 $\\frac{1}{n}<\\varepsilon$。（對 $x=\\frac{1}{\\varepsilon}$ 用第一種形式，得 $n>\\frac{1}{\\varepsilon}$，兩邊取倒數即可。）而且一旦 $\\frac{1}{n}<\\varepsilon$，對所有 $m\\ge n$ 也有 $\\frac{1}{m}\\le\\frac{1}{n}<\\varepsilon$。"],"tex":["\\forall\\varepsilon>0\\ \\exists n\\in\\mathbb{N},\\ \\frac1n<\\varepsilon"]},{"heading":"證明：$\\mathbb{N}$ 沒有上界","body":["反設 $\\mathbb{N}$ 有上界。$\\mathbb{N}$ 非空，由完備性公理 $s=\\sup\\mathbb{N}$ 存在。","$s-1<s$，所以 $s-1$ 不是 $\\mathbb{N}$ 的上界：存在 $n\\in\\mathbb{N}$ 使 $n>s-1$。","那麼 $n+1>s$，而 $n+1\\in\\mathbb{N}$，與 $s$ 是 $\\mathbb{N}$ 的上界矛盾。"],"collapsible":true},{"heading":"③ 推論：有理數在實數中稠密","body":["對任意實數 $a<b$，存在有理數 $q$ 使 $a<q<b$。想法：先選 $n$ 讓步長 $\\frac{1}{n}$ 比區間長度 $b-a$ 小，然後在數線上以 $\\frac{1}{n}$ 為步長往前走，一定有一步落進 $(a,b)$，跨不過去。"]},{"heading":"④ 在證明裡長什麼樣子","body":["之後的 $\\varepsilon$-$N$ 證明幾乎都會走到這一行：「要 $|a_n-L|<\\varepsilon$，只要 $n>$ 某個式子 $g(\\varepsilon)$ 就夠；由阿基米德性質取自然數 $N>g(\\varepsilon)$，則 $n\\ge N$ 時……」。$g(\\varepsilon)$ 是解不等式解出來的，可能是 $\\frac{1}{\\varepsilon}$、$\\frac{1}{\\varepsilon^2}$、$\\log_2(\\frac{1}{\\varepsilon})$。阿基米德性質保證這樣的 $N$ 一定存在，不管 $g(\\varepsilon)$ 有多大。範例 2 就是 $g(\\varepsilon)=\\frac{1}{\\varepsilon^2}$ 的例子。"]},{"heading":"證明：有理數稠密","body":["由阿基米德性質取 $n\\in\\mathbb{N}$ 使 $\\frac{1}{n}<b-a$。","整數集合 $\\{k\\in\\mathbb{Z}:k>na\\}$ 非空（阿基米德性質給一個比 $na$ 大的自然數），而且有下界（同理有整數 $-j<na$，比 $na$ 小的整數都不在集合裡）。有下界的非空整數集合有最小元，記為 $m$。","$m>na$，而 $m-1$ 不在集合裡，所以 $m-1\\le na<m$。除以 $n$：$a<\\frac{m}{n}\\le a+\\frac{1}{n}<a+(b-a)=b$。$q=\\frac{m}{n}$ 就是所求。"],"collapsible":true}],"workedExamples":[{"title":"$\\inf\\{\\frac{1}{n}\\}=0$","prompt":"證明 $\\inf\\{\\frac{1}{n}:n\\in\\mathbb{N}\\}=0$。","steps":["0 是下界：每個 $\\frac{1}{n}>0$。","0 是最大的下界：用 $\\varepsilon$ 判準（〈上確界與下確界〉的對稱版），要證對每個 $\\varepsilon>0$，存在 $n$ 使 $\\frac{1}{n}<0+\\varepsilon$。","這正是阿基米德性質的第二種形式。所以 $\\inf=0$。","0 不屬於集合（$\\frac{1}{n}=0$ 無解），所以這個下確界取不到。"],"answer":"$\\inf=0$，取不到"},{"title":"給定 $\\varepsilon$，算出 $N$","prompt":"要讓 $\\frac{1}{\\sqrt{n}}<10^{-3}$ 對所有 $n\\ge N$ 成立，最小的 $N$ 是多少？","problemId":"an-en-002","steps":["$\\frac{1}{\\sqrt{n}}<10^{-3}\\iff\\sqrt{n}>10^3\\iff n>10^6$（兩邊都是正數，取倒數、平方都保持方向）。","$n=10^6$ 時 $\\frac{1}{\\sqrt{n}}=10^{-3}$，不是嚴格小於，不行；$n=10^6+1$ 起都行，而且 $\\frac{1}{\\sqrt{n}}$ 遞減，之後每一項都更小。","最小的 $N=1000001$。"],"answer":"$N=1000001$"},{"title":"在 $\\sqrt{2}$ 與 $\\sqrt{2}+0.01$ 之間找有理數","prompt":"照稠密性的證明，找一個有理數 $q$ 使 $\\sqrt{2}<q<\\sqrt{2}+0.01$。","steps":["區間長度 0.01。取 $n$ 使 $\\frac{1}{n}<0.01$，$n=101$ 即可（$\\frac{1}{101}\\approx0.0099$）。","$na=101\\sqrt{2}\\approx142.8356$。比它大的最小整數 $m=143$。","$q=\\frac{143}{101}\\approx1.415842$。檢查：$\\sqrt{2}\\approx1.414214<1.415842<1.424214\\approx\\sqrt{2}+0.01$。"],"answer":"$q=\\frac{143}{101}$（答案不唯一，例如 1.415 也行）"}],"pitfalls":["把阿基米德性質當成不用證的常識。它在 $\\mathbb{R}$ 成立是因為完備性。","解 $\\frac{1}{n}<\\varepsilon$ 時取 $n=\\frac{1}{\\varepsilon}$。$\\frac{1}{\\varepsilon}$ 不一定是整數，而且等號不算；要取 $n>\\frac{1}{\\varepsilon}$。","稠密性的證明中，$n$ 沒先選好就去找 $m$，步長大過區間就可能整個跨過去。","以為「$\\mathbb{Q}$ 稠密」表示 $\\mathbb{Q}$ 填滿 $\\mathbb{R}$。稠密但仍然有洞，這是〈完備性公理〉那一課的重點。"],"voice":"f6e3bd14","sections":[{"title":"沒有無限大","beats":[{"show":["對每個實數 $x$，存在 $n\\in\\mathbb{N}$，$n>x$"],"note":"$\\mathbb{N}$ 在 $\\mathbb{R}$ 中沒有上界。","say":"不管 x 多大，總有自然數比它大。換句話說，自然數在實數裡沒有上界。","board":[{"do":"write","line":"$\\forall x\\in\\mathbb{R}\\ \\exists\\,n\\in\\mathbb{N}$：${{nx:n>x}}$"},{"do":"underline","term":"nx","label":"沒有上界","on":"換句話說","ms":3800}],"t":[0,8244]},{"show":["$\\forall\\varepsilon>0\\ \\exists n,\\ \\frac{1}{n}<\\varepsilon$"],"note":"對 $x=\\frac{1}{\\varepsilon}$ 用上一行，再取倒數。","say":"倒過來講：不管 epsilon 多小，只要是正的，總有 n 分之一比它小。","board":[{"do":"write","line":"$\\forall\\varepsilon>0\\ \\exists\\,n$：${{q:\\frac{1}{n}<\\varepsilon}}$"}],"t":[8532,15120]},{"show":["$m\\ge n$ ⇒ $\\frac{1}{m}\\le\\frac{1}{n}<\\varepsilon$"],"say":"而且一旦某個 n 做到了，比它大的每一個也都做到，因為分母越大，值越小。","board":[{"do":"write","line":"$m\\ge n$ ⇒ $\\frac{1}{m}\\le{{q:\\frac{1}{n}<\\varepsilon}}$","on":"比它大的","ms":2113}],"t":[15408,22464]},{"show":["$\\inf\\{\\frac{1}{n}\\}=0$"],"note":"0 是下界，而且這正是 $\\varepsilon$ 判準。取不到。","say":"所以 n 分之一的下確界是零：零是下界，往上退一點點就有某一項鑽到下面。","board":[{"do":"keep","n":2},{"do":"write","line":"$\\inf\\{\\frac{1}{n}\\}={{z:0}}$","on":"下確界","ms":1188},{"do":"underline","term":"z","color":"green","label":"下界","on":"零是下界","ms":2575}],"t":[22752,30456]},{"show":["$\\frac{1}{n}$ 一路往 0 靠"],"say":"看圖：n 分之一的點，一路往零靠近，永遠是正的。","board":[{"do":"plot","graph":{"window":[0,10,-0.2,1.2],"curves":[{"expr":"1/x","domain":[1,10],"color":"blue"}],"points":[{"x":1,"y":1},{"x":2,"y":0.5},{"x":4,"y":0.25},{"x":8,"y":0.125}]}}]},{"show":["任何 $\\varepsilon>0$：有 $\\frac{1}{n}<0+\\varepsilon$","所以 $\\varepsilon$ 不是下界"],"note":"比 0 大的數都不是下界，所以 0 最大。","say":"任何比零大的 epsilon，都有某個 n 分之一小於它，所以 epsilon 不是下界。這樣零就是最大的下界。","board":[{"do":"write","line":"$\\varepsilon>0$：${{w:\\frac{1}{n}<0+\\varepsilon}}$"},{"do":"underline","term":"w","label":"不是下界","on":"不是下界"}]}],"check":2},{"title":"它不是白送的","beats":[{"show":["有些有序數系有「無限大」的元素"],"note":"在 $\\mathbb{R}$ 裡成立，理由是完備性。","say":"這聽起來理所當然，但有一些有序的數系，裡面真的有比所有自然數都大的東西。","board":[{"do":"write","line":"有些有序數系：有比所有 $\\mathbb{N}$ 都大的元素"}],"t":[30744,38592]},{"show":["反設 $\\mathbb{N}$ 有上界","⇒ $s=\\sup\\mathbb{N}$ 存在"],"say":"在實數裡怎麼證？反設自然數有上界，完備性公理就給出它的上確界 s。","board":[{"do":"write","line":"反設 $\\mathbb{N}$ 有上界"},{"do":"write","line":"⇒ ${{sp:s=\\sup\\mathbb{N}}}$ 存在","on":"完備性公理"}],"t":[38880,46728]},{"show":["$s-1$ 不是上界"],"note":"比上確界小的數，都不是上界。","say":"s 減一比 s 小，所以不是上界，有某個自然數穿過它。接下來一步就矛盾了。","board":[{"do":"keep","n":1},{"do":"write","line":"$s-1<s$","on":"s 減一"},{"do":"write","line":"${{t:s-1}}$ 不是上界","on":"所以不是"},{"do":"underline","term":"t","label":"有 n 穿過","on":"穿過"}],"t":[47016,55368]},{"show":["$n>s-1$ ⇒ $n+1>s$","但 $s$ 是上界，要 $n+1\\le s$"],"note":"兩個式子互相衝突，所以反設不成立。","say":"n 大於 s 減一，兩邊加一，n 加一大於 s。可是 n 加一也是自然數，s 是上界，所以 n 加一不能超過 s，矛盾。","board":[{"do":"write","line":"$n>s-1$ ⇒ ${{a:n+1>s}}$"},{"do":"write","line":"但 $n+1\\in\\mathbb{N}$，要 ${{b:n+1\\le s}}$","on":"可是"},{"do":"arrow","from":"a","to":"b","color":"red","label":"衝突","on":"不能超過"}]}],"check":1},{"title":"取 $N>g(\\varepsilon)$","beats":[{"show":["只要 $n>g(\\varepsilon)$ 就夠"],"note":"$g(\\varepsilon)$ 是解不等式解出來的。","say":"之後的 epsilon N 證明，幾乎都走到這一行：解不等式，解出 n 只要大於某個式子就夠。","board":[{"do":"write","line":"解不等式 ⇒ 只要 $n>{{g:g(\\varepsilon)}}$","tint":{"g":"violet"}}],"t":[55656,63828]},{"show":["取自然數 $N>g(\\varepsilon)$"],"note":"不管 $g(\\varepsilon)$ 多大，這樣的 $N$ 都存在。","say":"然後取一個比它大的自然數 N。這一步為什麼合法？就是阿基米德性質。","board":[{"do":"write","line":"取自然數 ${{bn:N}}>{{g:g(\\varepsilon)}}$","tint":{"bn":"blue"}},{"do":"underline","term":"bn","label":"阿基米德性質","on":"就是阿基米德","ms":5613}],"t":[64116,72324]},{"show":["$\\frac{1}{\\sqrt{n}}<10^{-3}\\iff n>10^6$"],"note":"取倒數、平方，兩邊都是正數，方向不變。","say":"算一個：要根號 n 分之一小於十的負三次方，等價於 n 大於十的六次方。","board":[{"do":"write","line":"$\\frac{1}{\\sqrt{n}}<10^{-3}$"},{"do":"transform","line":"$\\frac{1}{\\sqrt{n}}<10^{-3}\\iff n>{{g6:10^6}}$","tint":{"g6":"violet"},"on":"等價於","ms":4063}],"t":[72612,79596]},{"show":["$n=10^6$：剛好等於，不行","最小的 $N=1000001$"],"say":"n 剛好等於十的六次方時是等號，不算。所以最小的 N 是十的六次方再加一。","board":[{"do":"keep","n":2},{"do":"write","line":"${{bad:n=10^6}}$：剛好等於","on":"剛好等於","ms":238},{"do":"strike","term":"bad","on":"不算","ms":3025},{"do":"write","line":"最小的 ${{bn:N}}=1000001$","color":"green","on":"所以最小的","ms":4350}],"t":[79884,88020]}],"key":"嚴格不等式：剛好等於不算數","check":0},{"title":"有理數很密","beats":[{"show":["任意 $a<b$，存在有理數 $q$，$a<q<b$"],"say":"阿基米德性質還有一個推論：任意兩個實數之間，一定有有理數。","board":[{"do":"write","line":"$\\forall a<b\\ \\exists\\,q\\in\\mathbb{Q}$：$a<q<b$"}],"t":[88308,94896]},{"show":["先選 $n$：$\\frac{1}{n}<b-a$"],"note":"步長比區間長度小。","say":"想法是：先挑 n，讓 n 分之一這個步長，比區間的長度還短。","board":[{"do":"write","line":"先選 $n$：${{h:\\frac{1}{n}}}<b-a$"}],"t":[95184,101664]},{"show":["以 $\\frac{1}{n}$ 為步長往前走"],"note":"一定有一步落進 $(a,b)$，跨不過去。","say":"然後在數線上一步一步往前走。步子比區間短，就不可能一步跨過整個區間。","board":[{"do":"write","line":"以 ${{st:\\frac{1}{n}}}$ 為步長往前走"},{"do":"underline","term":"st","color":"blue","on":"一步一步"}],"t":[101952,109980]},{"show":["第 $k$ 步走到 $\\frac{k}{n}$","$k$ 夠大，$\\frac{k}{n}>a$"],"note":"$\\frac{k}{n}$ 隨 $k$ 越來越大。","say":"第 k 步走到 n 分之 k。k 夠大時，由阿基米德性質，n 分之 k 一定超過 a。","board":[{"do":"write","line":"第 $k$ 步走到 $\\frac{k}{n}$"},{"do":"write","line":"$k$ 夠大 ⇒ ${{ov:\\frac{k}{n}>a}}$","on":"夠大"},{"do":"underline","term":"ov","label":"阿基米德","on":"阿基米德性質"}]},{"show":["前一步 $\\le a$","$\\frac{k}{n}\\le a+\\frac{1}{n}<b$"],"note":"第一個超過 $a$ 的點就在區間裡。","say":"取第一個超過 a 的那一步，前一步還沒超過 a。這一步只多走 n 分之一，比 b 減 a 短，到不了 b。","board":[{"do":"write","line":"前一步 $\\le a$"},{"do":"write","line":"$\\frac{k}{n}\\le a+{{st:\\frac{1}{n}}}<b$","on":"只多走"},{"do":"focus","term":"st","label":"比區間短","on":"比 b"}]}],"check":3},{"title":"證明：有理數稠密","beats":[{"show":["先選步長，再取第一個超過 $na$ 的整數"],"say":"策略：直接把有理數造出來。先選一個夠短的步長，再取第一個超過 n a 的整數當分子。","board":[{"do":"write","line":"先選步長，再取第一個超過 $na$ 的整數"}],"t":[110268,119340]},{"show":["取 $n\\in\\mathbb{N}$：$\\frac{1}{n}<b-a$"],"note":"阿基米德性質。","say":"由阿基米德性質，取 n，讓 n 分之一比區間長度 b 減 a 還小。","board":[{"do":"clear"},{"do":"write","line":"取 $n\\in\\mathbb{N}$：${{h:\\frac{1}{n}}}<b-a$","tint":{"h":"blue"},"on":"取 n","ms":1788}],"t":[119628,125892]},{"show":["$\\{k\\in\\mathbb{Z}:k>na\\}$ 有最小元 $m$"],"note":"非空、有下界的整數集合有最小元。","why":{"ask":"為什麼有最小元？","say":"比 n a 大的整數有無限多個。為什麼挑得出最小的？","options":[{"label":"非空、有下界的整數集合有最小元","correct":true},{"label":"它是 $\\mathbb{N}$ 的子集，用良序原理","why":"$na$ 可能是負的，集合裡會有負整數，不一定在 $\\mathbb{N}$ 裡；要先知道它有下界。"},{"label":"有下界的集合都有最小元","why":"實數集合不行：$(0,1)$ 有下界卻沒有最小元。這裡靠的是元素都是整數。"}],"t":[126180,132012]},"say":"阿基米德性質給出比 n a 大的自然數，所以非空；同理有比 n a 小的整數，它就是下界。整數集合這樣就有最小元。","board":[{"do":"write","line":"${{s:\\{k\\in\\mathbb{Z}:k>na\\}}}$ 有最小元 ${{m:m}}$","tint":{"m":"violet"}},{"do":"underline","term":"s","label":"非空、有下界","why":true,"on":"所以非空","ms":3250}],"t":[132300,143928]},{"show":["$k>na>-j$ ⇒ $k+j\\in\\mathbb{N}$","自然數非空子集有最小元（良序）"],"note":"整數集合有最小元，靠的是良序原理。","say":"每個 k 都大於負 j，加上 j 就變自然數。自然數的非空子集有最小元，這叫良序原理，所以它也有最小元。","board":[{"do":"write","line":"$k>na>-j$ ⇒ ${{kj:k+j}}\\in\\mathbb{N}$"},{"do":"write","line":"自然數非空子集有最小元","on":"這叫良序原理"}]},{"show":["$m-1\\le na<m$"],"note":"$m-1$ 不在集合裡。","why":{"ask":"為什麼 $m-1\\le na$？","say":"m 大於 n a。那 m 減一，為什麼就不大於 n a？","options":[{"label":"$m$ 是最小元，$m-1$ 不在集合裡","correct":true},{"label":"$m$ 和 $m-1$ 差 $1$","why":"差 $1$ 只說它們相鄰；$m-1\\le na$ 要靠 $m$ 是集合裡最小的。"},{"label":"$na$ 是整數","why":"$na$ 通常不是整數（例如 $101\\sqrt{2}$）；靠的是 $m$ 的最小性。"}]},"say":"m 是集合裡最小的，m 減一就不在集合裡，也就是 m 減一不大於 n a。","board":[{"do":"write","line":"${{m1:m-1}}\\le na<{{m:m}}$","on":"m 減一"},{"do":"underline","term":"m1","label":"不在集合裡","why":true,"on":"就不在"}]},{"show":["$a<\\frac{m}{n}\\le a+\\frac{1}{n}<b$"],"note":"除以 $n$，再用 $\\frac{1}{n}<b-a$。","say":"整串除以 n：a 小於 n 分之 m，不超過 a 加 n 分之一，又因為步長比區間短，小於 b。","board":[{"do":"write","line":"$a<\\frac{ {{m:m}} }{n}\\le a+{{h:\\frac{1}{n}}}<b$","on":"整串除以"},{"do":"focus","term":"h","label":"步長比區間短","on":"又因為"}]}],"key":"步長比區間短，第一個越過的點就落在裡面","proof":true,"of":5,"skeleton":"構造","where":{"ask":"「$\\frac{1}{n}<b-a$」用在哪一步？","steps":[{"label":"$\\{k\\in\\mathbb{Z}:k>na\\}$ 有最小元 $m$","why":"這一步只用到阿基米德性質給出非空、有下界，跟步長多短無關。"},{"label":"$m-1\\le na<m$","why":"這只用到 $m$ 是最小元。"},{"label":"$a<\\frac{m}{n}$","why":"這只用到 $m>na$。"},{"label":"$\\frac{m}{n}\\le a+\\frac{1}{n}<b$","correct":true}]}},{"title":"實際找一個","beats":[{"show":["找 $q$：$\\sqrt{2}<q<\\sqrt{2}+0.01$"],"say":"實際做一次：在根號二和根號二加零點零一之間，找一個有理數。","board":[{"do":"write","line":"$\\sqrt{2}<q<\\sqrt{2}+0.01$"}],"t":[165204,171900]},{"show":["$n=101$：$\\frac{1}{101}\\approx0.0099<0.01$"],"say":"區間長度零點零一，步長要比它短，取 n 等於一百零一。","board":[{"do":"write","line":"${{n:n=101}}$：$\\frac{1}{101}\\approx0.0099<0.01$"},{"do":"underline","term":"n","color":"blue","on":"取 n"}],"t":[172188,178056]},{"show":["$101\\sqrt{2}\\approx142.8356$"],"note":"取比它大的最小整數 $m$。","say":"a 乘 n 大約一百四十二點八三五六。m 取比它大的最小整數。","board":[{"do":"write","line":"$101\\sqrt{2}\\approx142.8356$"},{"do":"write","line":"$m$＝比 $101\\sqrt{2}$ 大的最小整數","on":"m 取"}],"t":[178344,185076]}],"predict":{"ask":"$m$ 是多少？","options":[{"label":"$143$，$q=\\frac{143}{101}\\approx1.415842$","correct":true},{"label":"比 $na$ 小的那個整數","why":"那樣 $\\frac{m}{n}<a$，落在 $\\sqrt{2}$ 左邊，不在區間裡。"},{"label":"$m=101$","why":"$\\frac{101}{101}=1$，比 $\\sqrt{2}$ 小；$m$ 要看 $na$，不是看 $n$。"}]}}],"checks":[{"ask":"$\\varepsilon=0.003$ 時，下列哪個 $n$ 能保證 $\\frac{1}{n}<\\varepsilon$？","options":[{"label":"$n=334$","correct":true},{"label":"$n=333$","why":"$\\frac{1}{333}\\approx0.003003>0.003$。要 $n>\\frac{1}{\\varepsilon}\\approx333.33$，333 差一點。"},{"label":"$n=300$","why":"$\\frac{1}{300}\\approx0.00333>0.003$。$n$ 越大 $\\frac{1}{n}$ 越小，300 太小了。"}]},{"ask":"證明 $\\mathbb{N}$ 沒有上界時，關鍵的一步是？","options":[{"label":"$s=\\sup\\mathbb{N}$ 時 $s-1$ 不是上界，所以有 $n>s-1$，於是 $n+1>s$","correct":true},{"label":"$\\mathbb{N}$ 是無限集合，所以沒有上界","why":"無限集合可以有上界，例如 $\\{1-\\frac{1}{n}\\}$。要用完備性才推得出來。"},{"label":"$n+1>n$，所以沒有最大的自然數","why":"這只證了 $\\mathbb{N}$ 沒有最大元。沒有最大元不代表沒有上界：$(0,1)$ 沒有最大元，上界卻是 1。"}]},{"ask":"阿基米德性質的「$\\frac{1}{n}$ 形式」是？","options":[{"label":"$\\forall\\varepsilon>0\\ \\exists n\\in\\mathbb{N},\\frac{1}{n}<\\varepsilon$","correct":true},{"label":"$\\exists n\\in\\mathbb{N}\\ \\forall\\varepsilon>0,\\frac{1}{n}<\\varepsilon$","why":"量詞對調了：同一個 $n$ 要小於所有正數 $\\varepsilon$，會逼出 $\\frac{1}{n}\\le0$，不可能。"},{"label":"$\\forall n\\in\\mathbb{N}\\ \\exists\\varepsilon>0,\\frac{1}{n}<\\varepsilon$","why":"這句太弱，取 $\\varepsilon=\\frac{1}{n}+1$ 就成立，什麼都沒說。"}]},{"ask":"要在 $a<b$ 之間找有理數 $\\frac{m}{n}$，為什麼先要 $\\frac{1}{n}<b-a$？","options":[{"label":"步長小於區間長度，以 $\\frac{1}{n}$ 為步長往前走才不會跨過 $(a,b)$","correct":true},{"label":"為了讓 $\\frac{m}{n}$ 是最簡分數","why":"最簡與否跟能不能落進區間無關；$q$ 不必是最簡分數。"},{"label":"為了讓 $n$ 是整數","why":"$n$ 本來就是自然數。條件 $\\frac{1}{n}<b-a$ 控制的是步長大小。"}]}],"practice":[{"id":"an-sup-001","core":true,"note":"證明最小性時用的就是「$\\frac{1}{n}<\\varepsilon$」。"},{"id":"an-en-002","core":true},{"id":"cg-12b-023","core":true},{"id":"cg-12b-026","core":true},{"id":"cg-12b-024"},{"id":"cg-12b-025"},{"id":"cg-12b-027"}]}});
